// Üretilen dosya: tool/ozgun/uret.py. Tarih · Anadolu uygarlıkları, Anadolu beylikleri ve Türkiye Selçuklu şehir-ticaret hayatı (Hitit, Urartu, Frig, Lidya, İyonya, beylikler, kervansaraylar, Ahilik) (kolay).
const ozHistory15Kolay = <(String, String, List<String>, String)>[
  ('Hattuşa arşivlerinde ele geçen kil tabletlerde kralların yalnızca kazandıkları zaferleri değil, seferlerde uğradıkları yenilgileri ve hataları da kaydettirmelerinin temel dinsel gerekçesi nedir?', 'Fırtına Tanrısı başta olmak üzere tanrılara hesap verme inancı', ['Komşu krallıkların elçilerine tarafsız görünebilme kaygısı', 'Pankuş meclisindeki soyluların denetim yetkisini sınırlandırma isteği', 'Babil yazıcılarının oluşturduğu kronik geleneğini taklit etme zorunluluğu'], 'Hitit kralları tanrılara karşı sorumlu olduklarına inandıkları için yıllıklarında (anal) başarıları kadar yenilgilerini de dürüstçe yazdırmışlardır.'),
  ('MÖ 13. yüzyılda Hititler ile Mısır arasında imzalanan Kadeş Antlaşması\'nın kil tablet nüshasında büyük kral Hattuşili\'nin mührünün yanında kraliçe Puduhepa\'nın mührünün de yer alması neyin göstergesidir?', 'Tavananna unvanlı kraliçenin diplomatik kararlarda resmî yetki taşıdığının', ['Kralın seferde bulunması nedeniyle antlaşmanın vekâleten onaylandığının', 'Mısır saray protokolünün antlaşmalarda kadın şahit şartı koştuğunun', 'Hitit toplumunda anaerkil miras hukukunun tümüyle egemen olduğunun'], 'Hititlerde Tavananna devlet yönetiminde, dış yazışmalarda ve dini törenlerde kralla birlikte söz sahibi olan üst düzey bir otoritedir.'),
  ('Urartu Kralı Menua döneminde inşa edilen ve yaklaşık elli kilometre boyunca uzanarak Van Ovası\'na tatlı su taşıyan mühendislik eseri aşağıdakilerden hangisidir?', 'Şamran Kanalı', ['Keşiş Gölü Bendi', 'Gordion Su Kemeri', 'Kral Yolu Drenajı'], 'Menua (Şamran) Kanalı, Urartuların sert coğrafyada tarımı geliştirmek için yaptığı dünyaca ünlü sulama kanalıdır.'),
  ('Hititlerin kendilerine ait yerel tanrıların yanı sıra fethettikleri ya da diplomatik ilişki kurdukları bölgelerin ilahlarını da tapınaklarına kabul etmeleri tarihçilerce hangi kavramla nitelendirilmiştir?', 'Bin Tanrı İli', ['Güneşin Çocukları', 'Kutsal Ocak Kültü', 'Yedi İklim Krallığı'], 'Çok tanrılı ve hoşgörülü bir din anlayışına sahip olan Hitit ülkesi kaynaklarda \'Bin Tanrı İli\' olarak anılmıştır.'),
  ('Doğu Anadolu\'nun sarp ve dağlık yapısı Urartu mimarisinde özellikle mezar geleneğini nasıl şekillendirmiştir?', 'Kayalara oyulmuş çok odalı aile mezarlarının yaygınlaşmasını sağlamıştır', ['Kerpiç piramit biçimli anıtsal yığma tepelerin yapılmasına yol açmıştır', 'Ölülerin akarsu yataklarına bırakılması geleneğini zorunlu kılmıştır', 'Ahşap kütüklerden örülü yer altı odalarının tercih edilmesini getirmiştir'], 'Urartular kayalık coğrafyaya uyum sağlayarak ölülerini eşyalarıyla birlikte sarp kayalıklara oydukları oda mezarlara defnetmişlerdir.'),
  ('Hitit Eski Krallık döneminde kralın yetkilerini denetleyen, gerektiğinde hükümdarı yargılayabilen ve soylu temsilcilerden oluşan danışma meclisi hangisidir?', 'Pankuş', ['Senato', 'Apella', 'Gerusia'], 'Pankuş Meclisi, Hitit Eski Krallık devrinde soylulardan oluşan ve kralın kararlarında etkili olan meclistir.'),
  ('Urartu krallarının Van Gölü\'nün doğu kıyısındaki sarp kayalık üzerine kurdukları ve uzun yıllar devletin yönetim merkezi olarak kullandıkları başkent hangisidir?', 'Tuşpa', ['Karkamış', 'Kültepe', 'Şapinuva'], 'MÖ 9. yüzyılda I. Sarduri tarafından kurulan Tuşpa (bugünkü Van Kalesi), Urartu Krallığı\'nın başkentidir.'),
  ('Hititlerden önce Anadolu\'da kurulan ancak Hitit Devleti\'nin doğuşuna zemin hazırlayan Hatti kültürünün en görkemli güneş kursları ve geyik heykelcikleri hangi merkezdeki kral mezarlarında bulunmuştur?', 'Alacahöyük', ['Çatalhöyük', 'Göbeklitepe', 'Aşıklıhöyük'], 'Alacahöyük\'teki Tunç Çağı Hatti prens/kral mezarlarından çıkan altın, gümüş ve tunç güneş kursları ile geyik figürleri Anadolu maden sanatının şaheserleridir.'),
  ('Hitit başkenti Hattuşa\'nın sur kapılarında yer alan anıtsal taş kabartma ve heykeller dikkate alındığında aşağıdakilerden hangisi bu kapılardan biri değildir?', 'İştar Kapısı', ['Aslanlı Kapı', 'Sfenksli Kapı', 'Kral Kapısı'], 'Aslanlı Kapı, Sfenksli Kapı ve Kral Kapısı Hattuşa\'dadır; sırlı tuğlalı İştar Kapısı ise Mezopotamya\'daki Babil kentine aittir.'),
  ('Urartu maden sanatının gelişmesinde devletin kurulduğu Doğu Anadolu coğrafyasının sunduğu hangi doğal üstünlük birinci derecede rol oynamıştır?', 'Zengin bakır, demir ve gümüş yataklarına yakınlık', ['Geniş alüvyal ovalarda pamuk tarımına elverişli iklim', 'Açık deniz limanları sayesinde kalay ticaretini tekelleştirme', 'Yüksek debili nehirlerde altın eleme kanallarının çokluğu'], 'Doğu Anadolu ve Ergani çevresindeki zengin demir, bakır ve gümüş madenleri Urartuların Ön Asya\'nın en usta metal işleyicileri olmasını sağlamıştır.'),
  ('Kayseri yakınlarındaki Kültepe (Kaniş) yerleşiminde Hititlerden hemen önce Anadolu\'da yazının tanınmasını sağlayan ticaret pazarlarına ne ad verilmiştir?', 'Karum', ['Agora', 'Bedesten', 'Ribat'], 'Asurlu tüccarların Anadolu şehirlerinin yanında kurdukları büyük ticaret merkezlerine \'Karum\', küçük konaklama pazarlarına ise \'Wabartum\' denilmiştir.'),
  ('Kültepe\'den çıkan Asur Ticaret Kolonileri Çağı belgelerine göre Asurlu tüccarların Mezopotamya\'dan eşek kervanlarıyla Anadolu\'ya getirdikleri başlıca iki ticaret malı hangileridir?', 'Kalay ve dokuma kumaşlar', ['Zeytinyağı ve mermer bloklar', 'Kereste ve işlenmemiş demir', 'İpek kozası ve porselen kaplar'], 'Anadolu\'da tunç üretimi için bakır bolken kalay az bulunduğundan, Asurlu tüccarlar Anadolu\'ya kalay ve kaliteli kumaş getirip karşılığında altın ve gümüş götürmüşlerdir.'),
  ('Hitit Devleti\'nin merkezi olan Hattuşa\'nın düz bir ova yerine engebeli, kayalık ve sarp yamaçlı Boğazköy arazisine kurulmuş olmasında hangi öncelik belirleyici olmuştur?', 'Doğal topoğrafyayı surlarla birleştirerek kentin savunulmasını kolaylaştırmak', ['Büyük ticaret gemilerinin nehir yoluyla saray kapısına yanaşmasını sağlamak', 'Volkanik kaplıca sularıyla kış aylarında saray odalarını ısıtmak', 'Çevredeki mermer ocaklarından sütun taşıma maliyetini sıfıra indirmek'], 'I. Hattuşili döneminde başkent yapılan Hattuşa, derin vadiler ve sarp kayalıklarla çevrili konumu sayesinde düşman ordularına karşı güçlü bir doğal savunma sağlamıştır.'),
  ('Urartu kaya mezarlarının iç duvarlarında yer alan dikdörtgen veya kare oyukların (nişlerin) arkeolojik buluntular ışığındaki kullanım amacı nedir?', 'Ölü hediyelerinin, kandillerin ve sunu kaplarının yerleştirilmesi', ['Mezar odasına temiz hava girmesini sağlayan baca kanalı açılması', 'Yağmur sularının tabanda birikmesini önleyen tahliye oluğu kurulması', 'Mezarı soymaya çalışanlar için mekanik ok tuzaklarının gizlenmesi'], 'Çok odalı Urartu kaya mezarlarındaki duvar nişleri, öteki dünya inancı gereği ölüye bırakılan takı, silah, kap ve aydınlatma kandilleri için açılmıştır.'),
  ('Urartu çivi yazısının Mezopotamya\'daki Asur çivi yazısından türetilmiş olmasına rağmen hece işaretlerinde yapılan sadeleştirme aşağıdakilerden hangisine örnektir?', 'Komşu uygarlıktan alınan kültürel unsurun yerel dil yapısına uyarlanmasına', ['Ticari sırların gizlenmesi amacıyla şifreli tapınak yazısı icat edilmesine', 'Asur valilerinin yerel dillerin konuşulmasını kesin olarak yasaklamasına', 'Hiyeroglif resim yazısından doğrudan Latin harf sistemine geçilmesine'], 'Urartular Asur çivi yazısını alırken kendi dilleri olan eklemeli Urartucaya uygun biçimde işaret sayısını azaltıp sadeleştirerek özgünleştirmişlerdir.'),
  ('Urartu ziraatında yüksek rakımlı ve sert kışlı Van Gölü havzasında elma, üzüm ve tahıl üretiminin binlerce yıl öncesinden başarılı olmasında belirleyici olan teknik uygulama nedir?', 'Dağ eteklerindeki kar sularını göletlerde toplayıp künk ve kanallarla teras bahçelere iletmek', ['Gölün sodalı ve tuzlu suyunu doğrudan buğday tarlalarına pompalamak', 'Ormanları tamamen yakarak küllü toprakta göçebe çapa tarımı yapmak', 'Yalnızca nehir taşkınlarının bıraktığı bataklık çamurunda çeltik yetiştirmek'], 'Van Gölü\'nün suyu sodalı olduğundan tarımda kullanılamaz; Urartular çevredeki dağlardan gelen tatlı kaynak ve kar sularını bent ve kanallarla ovalara indirmiştir.'),
  ('Hitit toplum yapısında kölelerin Mezopotamya ve Roma\'daki pek çok örneğin aksine mal mülk edinebilmesi, özgür kadınlarla evlenebilmesi ve bedel ödeyerek özgürlüğüne kavuşabilmesi neyi gösterir?', 'Kölelerin eşya değil, sınırlı da olsa hukuki kişiliğe sahip birey sayıldığını', ['Hitit ülkesinde sosyal sınıf ayrımının tamamen ortadan kaldırıldığını', 'Kölelerin Pankuş meclisinde soylularla eşit oy hakkına sahip olduğunu', 'Tarımsal üretimin yalnızca özgür rahipler tarafından gerçekleştirildiğini'], 'Hitit kanunları kölelere mülkiyet, evlilik ve tanıklık gibi belirli özel hukuk hakları tanıyarak onları salt konuşan alet olmaktan çıkarmıştır.'),
  ('Urartu kaya mimarisinde kalenin zirvesinden başlayıp kayanın içinden basamaklı tünellerle aşağıdaki su kaynağına veya ovaya inen gizli geçitlerin birincil işlevi nedir?', 'Uzun süreli kuşatmalarda kalenin su ihtiyacını güvenli biçimde karşılamak', ['Kış aylarında maden cevherini yer altında eritmek için fırın bacası olmak', 'Kral ailesinin yaz sıcaklarında serinlediği yer altı sarayı olarak kullanılmak', 'Halkın dini bayramlarda yer altı tanrılarına kurban attığı çukur olmak'], 'Doğu Anadolu\'daki pek çok Urartu kalesinde bulunan basamaklı kaya tünelleri, kuşatma sırasında düşmana görünmeden su kaynağına ulaşmak için açılmıştır.'),
  ('Hitit krallık ideolojisinde hükümdarın savaşta miğferli ve silahlı bir savaşçı, dini kabartmalarda ise ucu kıvrık asa (lituus) ve uzun cübbeyle tasvir edilmesi hangi iki yetkinin birleştiğini simgeler?', 'Askeri başkomutanlık ile dini başrahiplik', ['Deniz kaptanlığı ile lonca şeyhliği', 'Tüccarbaşılık ile hekimbaşılık', 'Mimarbaşılık ile vergi tahsildarlığı'], 'Hitit kralı savaş kıyafetiyle ordunun başkomutanı (Tabarna), uzun manto, takke ve ucu kıvrık asasıyla Güneş\'in ve tanrıların başrahibidir.'),
  ('Hitit taş kabartmalarında ve mühürlerinde sıkça rastlanan \'çift başlı kartal\' figürü Anadolu\'da hangi tarihsel sürekliliğin en çarpıcı simgelerinden biri olmuştur?', 'Binlerce yıl sonra Selçuklu mimarisinde de kudret ve hâkimiyet sembolü olarak yeniden kullanılmasının', ['Yalnızca kıyı kentlerindeki balıkçı loncalarının ticari damgası olarak kalmasının', 'Anadolu\'da tek tanrılı dinlerin doğuşuyla birlikte tamamen unutulmasının', 'Sadece mezar taşlarında ölümü simgeleyen uğursuz bir işaret sayılmasının'], 'Alacahöyük ve Yazılıkaya\'da görülen Hitit çift başlı kartal motifi, Anadolu\'daki kültürel miras etkileşimiyle Orta Çağ\'da Selçuklu ve Artuklu sanatında da yaşamıştır.'),
  ('Frig hukukunda saban kıran ya da koşum öküzünü bilerek öldüren bir kimseye ölüm cezasına varan çok ağır yaptırımlar uygulanmasının temel nedeni aşağıdakilerden hangisidir?', 'Ekonominin ve dini bereket inancının bütünüyle tarımsal üretime dayanması', ['Öküz derisinin uluslararası ticarette tek geçerli değişim aracı sayılması', 'Hayvancılıkla uğraşan göçebe boyların tarım arazilerini satın almasının önlenmesi', 'Askeri birliklerde savaş arabalarının yalnızca öküzlerle çekilmesinin zorunlu olması'], 'Friglerin geçim kaynağı tarım ve hayvancılık olduğu için üretim araçları olan öküz ve saban kanunlarla en ağır biçimde korunmuştur.'),
  ('MÖ 7. yüzyılda Lidya Krallığı\'nın başkent Sardes\'ten geçen Paktolos (Sart) Çayı\'nın alüvyonlarından elde ettiği doğal altın-gümüş karışımı madene dayanarak bastığı ilk madenî paralara ne ad verilir?', 'Elektron sikke', ['Gümüş drahmi', 'Bakır obolos', 'Altın dareikos'], 'Lidyalıların tarihte ilk kez devlet mührü vurarak bastıkları sikkeler, doğada altın ve gümüşün doğal alaşımı halinde bulunan \'elektron\' madeninden yapılmıştır.'),
  ('Lidya Devleti\'nin ticaret sayesinde olağanüstü zenginleşmesine rağmen MÖ 546 yılında Pers İmparatorluğu karşısında kısa sürede yıkılmasında hangi askeri zaaf belirleyici olmuştur?', 'Ordunun vatan bağlılığı zayıf, farklı kavimlerden toplanmış ücretli askerlerden oluşması', ['Sardes Kalesi\'nin etrafında hiçbir savunma surunun inşa edilmemiş olması', 'Demir silah yapımının bilinmemesi yüzünden yalnızca taş gürzler kullanılması', 'Donanmanın tüm gemilerinin Karadeniz\'deki fırtınada batmış bulunması'], 'Lidyalılar ticari zenginliklerine güvenerek savunmayı paralı askerlere bırakmış; milli bir ordunun bulunmaması Pers Kralı Kyros karşısında devletin hızla çökmesine yol açmıştır.'),
  ('Ege kıyılarında Efes, Milet, Foça ve İzmir gibi on iki kentten oluşan İyonya\'da felsefe, matematik ve doğa bilimlerinin Mezopotamya ve Mısır\'dan farklı olarak dogmalardan bağımsız gelişmesini sağlayan etken nedir?', 'Şehir devletlerinde baskıcı bir rahip sınıfının bulunmaması ve deniz ticaretiyle gelen refah', ['Merkezi bir imparatorun tüm bilginleri tek bir tapınak okulunda zorunlu eğitime tabi tutması', 'İç bölgelerle her türlü ticari ve kültürel temasın yasalarla kesilmiş olması', 'Yalnızca askeri teknolojilere bütçe ayrılarak edebiyat ve sanatın yasaklanması'], 'İyon polislerindeki siyasi özerklik, hoşgörülü toplumsal yapı, deniz ticaretinin sağladığı ekonomik bolluk ve farklı kültürlerle temas özgür düşünceyi doğurmuştur.'),
  ('Frig maden ustalarının geliştirdiği ve giysilerin omuzdan tutturulmasında kullanılan, günümüzdeki çengelli iğnenin ilk biçimi kabul edilen metal aksesuar hangisidir?', 'Fibula', ['Torkes', 'Diadem', 'Riton'], 'Yaylı kilit mekanizması ve makaralı kollarıyla Frig ustalarının mükemmelleştirdiği tunç, gümüş veya altın \'fibula\'lar dönem modasının ve metalürjisinin simgesidir.'),
  ('Batı Anadolu\'daki Sardes\'ten başlayıp Anadolu\'yu doğuya doğru kat ederek Mezopotamya\'daki Ninova ve Susa\'ya kadar uzanan ünlü ticaret ve haberleşme güzergâhı hangisidir?', 'Kral Yolu', ['Baharat Yolu', 'Kürk Yolu', 'Kehribar Yolu'], 'Lidyalılar döneminde ticari omurgası işleyen ve Persler döneminde posta teşkilatıyla geliştirilen Kral Yolu, Ege limanlarını Mezopotamya ve İran içlerine bağlamıştır.'),
  ('Friglerin doğa ve bereketin simgesi olarak dağlık kayalıklarda açık hava nişleri içinde tapındıkları, yanında aslan ve yırtıcı kuşlarla betimlenen ana tanrıçaları kimdir?', 'Kybele', ['Athena', 'Hera', 'Afrodit'], 'Anadolu\'nun binlerce yıllık Ana Tanrıça kültü Friglerde \'Matar Kubileya\' (Kybele) adıyla zirveye ulaşmış, buradan İyonya, Yunanistan ve Roma\'ya yayılmıştır.'),
  ('MÖ 585 yılında Kızılırmak (Halys) boylarında beş yıldır savaşan Lidya ve Med ordularının silah bırakıp barış antlaşması imzalamasına yol açan ve Miletli Thales\'in önceden hesapladığı doğa olayı nedir?', 'Tam Güneş tutulması', ['Şiddetli deprem ve heyelan', 'Kuyruklu yıldız geçişi', 'Kızılırmak\'ın taşkın yapması'], 'Thales\'in önceden öngördüğü 28 Mayıs MÖ 585 Güneş tutulması savaş sırasında gündüzü geceye çevirince Lidyalılar ve Medler bunu tanrıların uyarısı sayıp Halys Barışı\'nı yapmışlardır.'),
  ('Sözel edebiyatın en önemli türlerinden olan ve hayvanları konuşturarak insanlara ahlaki-siyasi dersler veren \'fabl\' türünün ilk büyük ustası Ezop\'un hangi Anadolu uygarlığı ortamında yetiştiği kabul edilir?', 'Frigya', ['Urartu', 'Hatti', 'Asur'], 'Antik kaynaklara göre MÖ 6. yüzyılda yaşayan masalcı Ezop (Aisopos) Frigyalıdır; hayvan öyküleri Frig kırsal kültürünün gözlem zenginliğini taşır.'),
  ('Efes\'te Lidya Kralı Kroisos\'un da sütun bağışlarıyla desteklediği, İyon düzeninin en görkemli örneklerinden biri olup Antik Dünyanın Yedi Harikası arasında sayılan kutsal yapı hangisidir?', 'Artemis Tapınağı', ['Didyma Apollon Tapınağı', 'Pergamon Zeus Sunağı', 'Athena Polias Tapınağı'], 'Anadolu\'nun Ana Tanrıçası Kybele ile özdeşleşen Efes Artemis\'i adına mermerden inşa edilen dev tapınak, antik dünyanın yedi harikasından biridir.'),
  ('Paranın (sikkenin) Lidyalılar tarafından icat edilerek Akdeniz ve Yakın Doğu ticaretinde yaygınlaşmasının ekonomik hayatta yarattığı en köklü dönüşüm aşağıdakilerden hangisidir?', 'Takas usulünün zorluklarını aşarak değer ölçüsü, birikim ve uzak mesafe ticaretini hızlandırması', ['Devletlerin gümrük ve pazar vergisi toplama yetkisini tamamen ortadan kaldırması', 'Tarımsal üretimin sona erip tüm nüfusun maden işçiliğine yönelmesine yol açması', 'Kervan yollarının önemini yitirerek kara ulaşımının bütünüyle terk edilmesi'], 'Standart ağırlık ve saflığı devletçe garanti edilen sikke, malın malla değişimindeki (trampa) uyuşmazlıkları çözerek sermaye birikimini ve ticaret hacmini büyütmüştür.'),
  ('MÖ 7. yüzyıl başında Kafkaslar üzerinden Anadolu\'ya yayılan Kimmerlerin başkent Gordion\'u yakıp yıkması üzerine boğa kanı içerek yaşamına son verdiği rivayet edilen efsanevi Frig kralı kimdir?', 'Midas', ['Gordios', 'Kroisos', 'Telepinuş'], 'Asur belgelerinde \'Mita\' olarak geçen Frig Kralı Midas, MÖ 696/695 dolaylarında Kimmer istilasıyla Gordion\'un düşmesi sonucu egemenliğini kaybetmiştir.'),
  ('Antik Çağ\'da \'Tarihin Babası\' unvanıyla anılan ve Pers-Yunan savaşları ile Anadolu, Mezopotamya ve Mısır kültürlerini incelediği ünlü \'Historia\' eserini yazan Herodot hangi Anadolu kentinde doğmuştur?', 'Halikarnas (Bodrum)', ['Gordion (Polatlı)', 'Tuşpa (Van)', 'Hattuşa (Boğazköy)'], 'MÖ 5. yüzyılda yaşayan Herodot, Karya bölgesinin ünlü kıyı kenti Halikarnassos\'ta (günümüz Bodrum) dünyaya gelmiştir.'),
  ('İstanköy (Kos) adası ve Batı Anadolu İyon kültür çevresinde yetişen Hipokrat\'ın tıp bilimine yaptığı en devrimci katkı aşağıdakilerden hangisidir?', 'Hastalıkları tanrıların cezası veya büyü yerine doğal-fizyolojik nedenlerle açıklaması', ['Ameliyatlarda röntgen ışınlarıyla kırık kemikleri görüntülemesi', 'Bulaşıcı virüslere karşı laboratuvarda antibiyotik sentezlemesi', 'Yalnızca kral ailesini tedavi edip halk hekimliğini yasaklaması'], 'Hipokrat tıp bilimini büyü ve tapınak kehanetlerinden ayırarak gözlem, klinik bulgu, beslenme ve doğal neden-sonuç temeline oturtmuştur.'),
  ('Antalya\'nın Demre ilçesi yakınlarındaki Myra ve Kaş ilçesindeki Antiphellos antik kentleri Anadolu\'daki hangi uygarlık birliğinin önemli liman ve kültür merkezleridir?', 'Likya Uygarlığı', ['Frigya Krallığı', 'Lidya Devleti', 'Urartu Krallığı'], 'Teke Yarımadası\'nda yer alan Myra, Ksantos, Patara, Olympos, Phaselis ve Antiphellos kentleri Likya Birliği\'nin başlıca yerleşimleridir.'),
  ('Büyük İskender\'in MÖ 333 kışında Gordion\'a geldiğinde Zeus Tapınağı\'ndaki kızılcık kabuğundan örülmüş ünlü \'Gordion Düğümü\'nü kılıcıyla kesmesi hangi siyasi propagandaya hizmet etmiştir?', 'Düğümü çözen kişinin tüm Asya\'nın hâkimi olacağı kehanetini kendi lehine gerçekleştirme', ['Frig rahiplerinin koyduğu tarım vergilerini resmen yürürlükten kaldırma', 'Anadolu\'daki tüm ahşap savaş arabalarının imha edilmesini emretme', 'Makedonya ordusunun artık doğuya ilerlemeyip Yunanistan\'a döneceğini ilan etme'], 'Kral Gordios\'un kağnısındaki kördüğümü çözenin Asya\'ya hükmedeceği inancını bilen Büyük İskender, düğümü kılıcıyla keserek Asya seferi için psikolojik meşruiyet sağlamıştır.'),
  ('Sisam (Samos) adasında doğup İyonya bilim ortamında yetişen Pisagor\'un (Pythagoras) felsefe ve bilime getirdiği özgün bakış açısı nedir?', 'Evrenin uyumunu ve müzik aralıklarını sayısal oranlar ile geometri ilkeleriyle açıklaması', ['Tüm doğa olaylarını yalnızca suyun buharlaşması ve yoğunlaşmasına indirgemesi', 'Matematiksel ispat yerine halk söylencelerini bilimin tek kaynağı sayması', 'Yeryüzünün düz bir tepsi şeklinde sonsuz okyanus üzerinde yüzdüğünü savunması'], 'Pisagor \'Her şey sayıdır\' ilkesiyle geometri teoremlerini ve müzikteki ses aralıklarının matematiksel oranlarını sistematik hale getirmiştir.'),
  ('Perslerin MÖ 546\'da Sardes\'i ele geçirmesinden sonra Anadolu\'yu \'satraplık\' adı verilen eyaletlere ayırıp Kral Yolu boyunca düzenli menzil istasyonları kurmalarının birincil amacı nedir?', 'Geniş coğrafyada merkezi denetimi, hızlı haberleşmeyi ve vergi akışını güvenceye almak', ['Anadolu\'daki tüm yerli dilleri ve yerel dinleri kısa sürede ortadan kaldırmak', 'İyon limanlarını kapatarak deniz ticaretini bütünüyle Fenikelilere devretmek', 'Yerli halkı İran yaylasına göç ettirip Anadolu\'yu insansız tampon bölge yapmak'], 'Persler Anadolu\'da kültürel hoşgörü gösterirken satraplık idaresi, şah gözü-kulağı denetçileri ve Kral Yolu posta ağlarıyla sıkı bir siyasi-mali kontrol kurmuşlardır.'),
  ('İyonya\'nın kuzey sınırındaki Phokaia (Foça) kentinin adını ve bastığı elektron sikkelerin üzerindeki simgeyi Akdeniz fokundan (\'phoke\') alması neyin göstergesidir?', 'Kent kimliğinin ve ekonomisinin tümüyle deniz ekosistemi ve denizcilikle bütünleştiğinin', ['Halkın fok balığını baş tanrı ilan ederek tarımı dinen yasakladığının', 'Foçalıların Kuzey Buz Denizi\'nden göç ederek Ege\'ye yerleştiğinin', 'Fok derisinin kâğıt yerine resmi antlaşmalarda kullanıldığının'], 'Denizci bir İyon kenti olan Phokaia, kıyı kayalıklarında yaşayan Akdeniz fokunu kentin arması yapmış ve sikkelerine fok kabartması basmıştır.'),
  ('Miletos kentinin dört ayrı doğal limana sahip bir yarımada üzerinde yükselirken yüzyıllar içinde denizle bağlantısını yitirerek içeride bir ova kalıntısına dönüşmesinin coğrafi nedeni nedir?', 'Büyük Menderes (Maiandros) Nehri\'nin taşıdığı alüvyonlarla körfezi doldurması', ['Büyük bir volkanik patlamayla kıyı şeridinin yüz metre yükselmesi', 'Romalıların düşman gemilerini engellemek için körfeze taş dökmesi', 'Ege Denizi\'ndeki su seviyesinin buzul çağı nedeniyle çekilmesi'], 'Efes\'i Küçük Menderes\'in, Milet ve Priene\'yi ise Büyük Menderes Nehri\'nin getirdiği alüvyonların doldurması sonucu bu ünlü İyon liman kentleri kıyıdan kilometrelerce içeride kalmıştır.'),
  ('Lidya Kralı Kroisos\'un Perslere karşı sefere çıkmadan önce Delfi ve Didyma kâhinlerine gönderdiği elçilere aldığı \'Kızılırmak\'ı geçersen büyük bir imparatorluğu yıkacaksın\' yanıtının tarihsel sonucu ne olmuştur?', 'Kroisos\'un Persleri yıkacağını sanarak ırmağı geçmesi ve kendi Lidya Krallığı\'nın yıkılması', ['Pers ordusunun kehanetten korkarak savaşmadan Mezopotamya\'ya geri çekilmesi', 'Lidya ve Pers krallarının Kızılırmak ortasında ticaret köprüsü kurup birleşmesi', 'İyon şehirlerinin Lidya safında savaşa girerek Pers başkentini ele geçirmesi'], 'İki anlamlı kehaneti kendi zaferi olarak yorumlayan Kroisos MÖ 547/546\'da Halys\'i (Kızılırmak) geçmiş, ancak Kyros\'un takibiyle Sardes düşmüş ve yıkılan devlet kendi krallığı olmuştur.'),
  ('Lidyalıların ticaret hayatında geliştirdikleri tefecilik/kredi işlemleri ve emanet altın saklama uygulamaları iktisat tarihinde hangi kurumsal yapının ilk adımları arasında değerlendirilir?', 'Erken dönem sarraflık ve bankacılık faaliyetlerinin', ['Anonim hisse senedi borsalarının', 'Kağıt banknot basım tekelinin', 'Kooperatif tarım sigortacılığının'], 'Sardes\'teki tapınaklar (özellikle Artemis Tapınağı) ve sarraflar, değerli madenlerin güvenle saklanması, tartılması ve borç verilmesiyle antik bankacılığın öncüsü olmuştur.'),
  ('Likya\'daki Myra, Limyra ve Pinara tiyatroları ile kaya mezarlarının şehir dokusuyla kurduğu ilişki incelendiğinde Anadolu antik şehirciliğinin hangi temel ilkesi görülür?', 'Doğal yamacın eğimini bozmadan yapıları topoğrafyayla uyumlu biçimde kademelendirme', ['Dağları tamamen düzleştirerek tüm binaları deniz seviyesinde tek düzleme oturtma', 'Mezarlıkları şehir surlarından en az bir günlük yürüyüş mesafesi uzağa gizleme', 'Kamu binalarını yalnızca kerpiçten yapıp taş kullanımını saraylara özgü kılma'], 'Anadolu antik kentlerinde tiyatrolar ve kaya mezarları doğal arazi eğimine yaslanarak topoğrafyayla bütünleşik, görkemli bir kentsel peyzaj oluşturmuştur.'),
  ('1071 Malazgirt Zaferi\'nin hemen ardından Sultan Alparslan\'ın komutanlarına \'Fethettiğiniz yerler sizin mülkünüzdür\' diyerek yetki tanıması Türk İslam hukukunda hangi geleneksel ilkeyle ifade edilir?', 'Kılıç hakkı', ['Müsadere ve merkezi hazineye devir usulü', 'İltizam yoluyla açık artırmalı vergi ihalesi', 'Beşinci hisse üzerinden pençik tahsilatı'], 'Malazgirt sonrasında Anadolu\'nun hızla Türkleşmesini sağlayan temel politika, fethedilen toprağın fetheden komutana yurtluk olarak bırakıldığı \'kılıç hakkı\' uygulamasıdır.'),
  ('Malazgirt Savaşı sonrasında Erzurum ve çevresinde Ebu\'l-Kasım tarafından kurularak Anadolu\'daki ilk Türk beyliği olma özelliğini taşıyan siyasi teşekkül hangisidir?', 'Saltuklular', ['Batı Anadolu kıyılarında yükselen Aydınoğulları', 'Çukurova bölgesinde egemen olan Ramazanoğulları', 'Sinop ve Kastamonu hattında kurulan Candaroğulları'], '1072 yılında Erzurum merkezli kurulan Saltuklular, Malazgirt\'ten sonra Anadolu\'da teşkilatlanan ilk Türk beyliğidir.'),
  ('İzmir ve çevresini ele geçirerek 1081 yılında kırk parçalık bir filo inşa ettiren ve Türk denizcilik tarihinin başlangıcını simgeleyen komutan kimdir?', 'Çaka Bey', ['Diyarbakır ve Mardin havzasında hüküm süren Artuk Bey', 'Erzincan ve Kemah kalelerini fetheden Mengücek Gazi', 'Orta Anadolu\'da Haçlı ordularını durduran Gümüştekin'], 'Bizans sarayında denizciliği de yakından tanıyan Çaka Bey, 1081\'de İzmir\'de ilk Türk donanmasını kurmuş ve bu yıl Deniz Kuvvetlerinin kuruluş yılı sayılmıştır.'),
  ('Sivas\'ın Divriği ilçesinde Mengücekliler döneminde Ahmet Şah ve eşi Melike Turan Melek tarafından 1228\'de yaptırılan, taç kapılarındaki taş gölge ve bezeme ustalığıyla UNESCO Dünya Mirası Listesi\'ne giren eser hangisidir?', 'Divriği Ulu Camii ve Darüşşifası', ['Erzurum merkezindeki Çifte Minareli Medrese Külliyesi', 'Konya Alaeddin Tepesi\'ndeki Karatay Çini Medresesi', 'Ağrı Doğubayazıt yamaçlarındaki İshak Paşa Sarayı'], 'Ahlatlı Hürremşah\'ın başmimarı olduğu Divriği Ulu Camii ve Darüşşifası, 1985 yılında Türkiye\'den UNESCO Dünya Mirası Listesi\'ne alınan ilk İslam mimarisi şaheseridir.'),
  ('Artukluların Hasankeyf ve Diyarbakır saraylarında yirmi beş yılı aşkın süre başmühendislik yapan, su ve mekanik denge ilkeleriyle çalışan otomatlar tasarlayarak sibernetik biliminin öncüsü sayılan bilgin kimdir?', 'El-Cezerî', ['Semerkant rasathanesinde yıldız kataloğu hazırlayan Uluğ Bey', 'Tıp Kanunu adlı eseriyle Avrupa\'da okutulan İbn-i Sina', 'Optik biliminin temellerini deneylerle kuran İbnü\'l-Heysem'], 'Cizreli Ebu\'l-İz İbnü\'r-Rezzaz el-Cezerî, Artuklu hükümdarı Nasıreddin Mahmud\'un isteğiyle 1206\'da yazdığı \'Kitabü\'l-Hiyel\' eseriyle robotik ve sibernetiğin öncüsü kabul edilir.'),
  ('Batman Çayı üzerinde 1147 yılında Artuklu hükümdarı Timurtaş tarafından yaptırılan, kırk metreyi aşan sivri ana kemer açıklığı ve yanlarındaki konaklama odalarıyla dünyaca tanınan mühendislik yapısı hangisidir?', 'Malabadi Köprüsü', ['Edirne\'de Meriç Nehri üzerine kurulan Uzun Köprü', 'Adana\'da Seyhan Irmağı üzerindeki Roma Taş Köprü', 'Büyükçekmece Gölü ağzındaki Mimar Sinan Köprüsü'], 'Artuklu döneminin başyapıtı olan Malabadi Köprüsü, döneminin en geniş taş kemerli köprüsü olup içinde yolcuların barınacağı odalar bile barındırmaktadır.'),
  ('Erzurum\'da Saltuklular döneminden günümüze ulaşan \'Tepsi Minare (Saat Kulesi)\', \'Kale Camii\' ve \'Üç Kümbetler\' yapıları ilk Türk beyliklerinin Anadolu\'daki hangi kalıcı etkisini kanıtlar?', 'Göçebe askeri güç olmaktan çıkıp Türk-İslam şehir dokusunu bayındır eserlerle kurduklarını', ['Mimari yapıların tamamında yalnızca ahşap ve çadır malzemesi kullandıklarını', 'Eski Urartu tapınaklarını hiçbir değişiklik yapmadan camiye çevirdiklerini', 'Şehir merkezlerini terk ederek sadece kırsal yaylalarda konakladıklarını'], 'Saltuklular Erzurum\'da inşa ettikleri cami, kümbet ve kervansaraylarla Anadolu\'da kalıcı kentsel Türk mimarisinin ilk anıtsal örneklerini vermişlerdir.'),
  ('1071 sonrasında kurulan İlk Türk Beyliklerinin Anadolu tarihindeki genel işlevleri değerlendirildiğinde aşağıdakilerden hangisi bu beyliklerin ortak katkılarından biri olarak gösterilemez?', 'Moğol İlhanlı ordularını Kösedağ\'da yenerek Anadolu\'dan tamamen çıkarmaları', ['Gürcü, Ermeni, Bizans ve Haçlı kuvvetlerine karşı Anadolu\'yu savunmaları', 'Dağ, nehir, ova ve yerleşim yerlerine Türkçe isimler vererek coğrafyayı vatanlaştırmaları', 'Cami, medrese, darüşşifa ve köprülerle İslam şehircilik kültürünü yerleştirmeleri'], 'İlk Türk beyliklerinin büyük çoğunluğu 1243 Kösedağ Savaşı\'ndan önce Türkiye Selçukluları veya Eyyubiler tarafından ilhak edilmiş; Moğolları yenmek gibi bir durum söz konusu olmamıştır.'),
  ('Divriği Ulu Camii ve Darüşşifası\'nda şifahane kısmının ortasındaki havuzdan akan suyun sesi ve kubbe akustiğiyle hastaların tedavi edilmesi İslam tıbbındaki hangi yaklaşımı yansıtır?', 'Ruh ve sinir hastalıklarının su sesi ve musiki makamlarıyla iyileştirilmesini', ['Bulaşıcı salgınların soğuk su şokuyla karantina altına alınmasını', 'Cerrahi ameliyatların yalnızca gece karanlığında yapılmasını', 'İlaç kullanımı yerine hastaların aç bırakılarak arındırılmasını'], 'Selçuklu ve Mengücekli darüşşifalarında bedensel hastalıkların yanında akıl ve ruh hastalıkları da su şırıltısı, ferah akustik ve müzikle tedavi edilmekteydi.'),
  ('Danişmendlilerin Anadolu\'da Türkiye Selçuklularından bile önce kendi adlarına madenî para bastırmış olmaları (Danişmend Gazi ve Emir Gazi sikkeleri) neyin hukuki göstergesidir?', 'Egemenlik ve bağımsızlık alametlerini erken aşamada benimsediklerinin', ['Anadolu\'daki tüm altın madenlerini tek başlarına işlettiklerinin', 'Abbasi Halifesi\'nin dünyevi ve dini otoritesini reddettiklerinin', 'Selçuklu sultanlarına her yıl haraç ödemek zorunda kaldıklarının'], 'İslam devlet geleneğinde hutbe okutmakla birlikte kendi adına sikke (para) kestirmek hükümdarlığın ve siyasi egemenliğin en temel sembolüdür.'),
  ('Kayseri\'de Danişmendliler devrinden kalan \'Kölük Camii ve Medresesi\' ile Niksar\'daki \'Yağıbasan Medresesi\'nin bitişik veya bütünleşik planlanması Türk-İslam kentleşmesinde neyi yansıtır?', 'İbadet mekânı ile yükseköğretim kurumunun sosyal hayatın merkezinde iç içe kurgulandığını', ['Medrese öğrencilerinin şehir dışına çıkmasının ömür boyu yasaklandığını', 'Taş ustalarının ayrı bina yapacak teknik bilgiye sahip olmadığını', 'Sadece din adamlarının çocuklarına okuma yazma öğretildiğini'], 'İlk Türk beyliklerinde cami ve medrese çoğu kez aynı külliye içinde ya da bitişik inşa edilerek ilim ile ibadetin bütünlüğü vurgulanmıştır.'),
  ('Kayseri\'deki \'Güllük (Kölük) Külliyesi\' ve Sivas-Kayseri hattındaki erken dönem \'kümbet\' mimarisinde altta cenazelik (mumyalık) katı, üstte mescit katı ve dışta piramidal/konik külah bulunması hangi geleneğin devamıdır?', 'Türklerin İslamiyet öncesi kurgan ve otağ (çadır) kültürünün İslami anıt mezara dönüşmesinin', ['Likya ev tipi kaya mezarlarının Orta Anadolu\'ya aynen taşınmasının', 'Roma zafer sütunlarının içlerinin oyularak türbe yapılmasının', 'Babil zigguratlarının küçültülmüş tuğla maketlerinin kurulmasının'], 'Anadolu\'daki kümbet mimarisi; altındaki mumyalık odasıyla kurgan geleneğini, silindirik/çokgen gövdesi ve konik külahıyla ise Türk otağ (çadır) biçimini yaşatmaktadır.'),
  ('İlk Türk beyliklerinin kurulduğu 1071-1178 arasındaki yüzyıllık dönemde Danişmendliler, Saltuklular, Mengücekliler ve Artuklular arasında zaman zaman sınır çatışmaları yaşansa da ortak dış tehdit belirdiğinde nasıl bir tutum izlenmiştir?', 'Haçlı seferlerine ve Gürcü-Bizans saldırılarına karşı ittifak kurarak birlikte savaşmışlardır', ['Dış düşmanlarla anlaşarak komşu Türk beyliklerinin tamamını ortadan kaldırmışlardır', 'Savaşmaktan kaçınarak tüm şehirleri boşaltıp İran\'a geri çekilmişlerdir', 'Abbasi Halifesi\'nden gelen paralı ordular gelene dek kalelerinden çıkmamışlardır'], 'İç rekabete rağmen Haçlı orduları veya Gürcü saldırıları karşısında Danişmendli, Selçuklu, Artuklu ve Saltuklu kuvvetleri derhal birleşerek Anadolu\'yu savunmuşlardır.'),
  ('İlk Türk beyliklerinden Danişmendlilerin Sivas, Kayseri, Tokat, Amasya ve Malatya gibi geniş bir coğrafyaya hâkim olmalarına rağmen 12. yüzyılın ikinci yarısında hızla zayıflamalarının iç nedeni nedir?', 'Ülkenin hanedan üyelerinin ortak malı sayılması anlayışıyla üç ayrı kola bölünüp taht kavgalarına düşmesi', ['Tarımsal üretimin tamamen terk edilerek yalnızca madencilikle uğraşılması', 'Yerli Hristiyan halka ağır dini baskı uygulanması sonucu isyan çıkması', 'Donanma giderlerinin hazineyi kısa sürede iflasa sürüklemesi'], 'Melik Mehmed Gazi\'nin ölümünden (1142) sonra Danişmendlilerin Sivas, Malatya ve Kayseri kollarına ayrılıp birbirleriyle çatışması Türkiye Selçuklularının onları ilhakını kolaylaştırmıştır.'),
  ('1071 Malazgirt Savaşı\'ndan sonra kurulan ilk Türk beyliklerinin mimari eserlerinde İran Büyük Selçuklu geleneğindeki tuğla ve sırlı çini yerine kesme taşın başat malzeme haline gelmesi nasıl açıklanır?', 'Anadolu coğrafyasındaki zengin taş ocaklarına ve köklü yerel taş işçiliği birikimine uyum sağlanmasıyla', ['İslam hukukunda tuğla pişirme fırınlarının şehir yakınında kurulmasının yasaklanmasıyla', 'Tuğla yapımında kullanılan kil yataklarının Anadolu\'da hiç bulunmamasıyla', 'Bizans imparatorlarının Türk beylerine tuğla satılmasına ambargo koymasıyla'], 'Türkler İran\'da tuğla kullanırken Anadolu\'ya geldiklerinde kalker, bazalt ve tüf gibi zengin taş kaynaklarını görerek geleneksel planlarını anıtsal kesme taş mimarisine dönüştürmüşlerdir.'),
  ('Artuklu saraylarında ve şehirlerinde Süryani, Ermeni, Rum ve Müslüman ustaların bir arada çalışıp kiliseler ile camilerin yan yana varlığını sürdürmesi beyliğin hangi yönetim ilkesini gösterir?', 'Zımmi hukukuna dayalı toplumsal hoşgörü ve birlikte yaşama kültürünü benimsediğini', ['Merkezi otoritenin zayıflığı yüzünden şehirlerde asayişin sağlanamadığını', 'Bütün gayrimüslim nüfusun vergiden tamamen muaf tutulduğunu', 'Devlet yönetiminde şer\'i ve örfi hukukun yürürlükten kaldırıldığını'], 'Mardin, Diyarbakır ve Harput\'ta Artuklular farklı din ve mezhepten tebaaya geniş ibadet ve zanaat özgürlüğü tanımış; Deyrulzafaran gibi manastırlar bu dönemde güvenle yaşamıştır.'),
  ('İlk Türk beyliklerinden Çaka Beyliği\'nin 1081-1093 arasındaki kısa ömrüne rağmen diğer iç bölge beyliklerinden ayrılan en özgün tarihsel misyonu aşağıdakilerden hangisidir?', 'Türklerin kara ordusu geleneğini ilk kez açık deniz stratejisi ve ada fetihleriyle birleştirmesi', ['Anadolu\'da ilk kez kervansaray ve devlet sigortası sistemini başlatması', 'Abbasi Halifesi\'ni İzmir\'de koruma altına alarak dini liderliği üstlenmesi', 'İpek Yolu üzerindeki tüm gümüş madenlerini devlet tekeline alması'], 'Diğer ilk beylikler kara hâkimiyeti ve kale savunmasına odaklanırken Çaka Beyliği Ege\'de tersane kurup adaları fethederek Türk denizcilik ufkunu açmıştır.'),
  ('Malazgirt\'ten sonra kurulan ilk Türk beyliklerinin yaklaşık bir asır içinde Anadolu\'yu \'Romania\' (Rum Diyarı) olmaktan çıkarıp Batılı kaynaklarda \'Turchia\' (Türkiye) olarak anılır hale getirmesinde hangi unsur en etkili olmuştur?', 'Askeri fetihleri yoğun Oğuz göçü, tarımsal iskân ve kalıcı vakıf eserleriyle bütünleştirmeleri', ['Anadolu\'daki tüm eski yolları ve köprüleri yıkarak ulaşımı kesmeleri', 'Yalnızca ganimet toplayıp kış aylarında Horasan\'a geri dönmeleri', 'Bizans saray protokolünü ve Grek dilini resmi kimlik olarak benimsemeleri'], '12. yüzyıldan itibaren Batılı Haçlı kroniklerinin Anadolu\'ya \'Turchia\' demesinin sebebi, ilk beylikler ve Türkiye Selçuklularının kurduğu yoğun Türk nüfusu ve vakıf medeniyetidir.'),
  ('Büyük Selçuklu hükümdarı Melikşah döneminin başlarında İznik\'i fethederek 1075 yılında Türkiye Selçuklu Devleti\'nin temellerini atan hanedan üyesi kimdir?', 'Kutalmışoğlu Süleymanşah', ['Büyük Selçuklu ordusunun öncü birliklerini yöneten Afşin Bey', 'Malazgirt sonrasında Erzurum havzasına yerleşen Ebu\'l-Kasım', 'Suriye Selçuklu kolunu Halep merkezli örgütleyen Tutuş Bey'], 'Arslan Yabgu soyundan gelen Kutalmışoğlu Süleymanşah, 1075\'te Bizans\'ın önemli kenti İznik\'i ele geçirip başkent yaparak Türkiye Selçuklu Devleti\'ni kurmuştur.'),
  ('I. Haçlı Seferi sırasında kalabalık Haçlı ordularının İznik\'i kuşatması ve 1097 Eskişehir (Dorileon) Muharebesi sonrasında Sultan I. Kılıçarslan devlet merkezini hangi şehre taşımıştır?', 'Konya', ['Kızılırmak kavsinde yüksek surlarla çevrili bulunan Sivas', 'Karadeniz ticaret yollarının kavşak noktasındaki Amasya', 'Toros geçitlerini kuzeyden denetleyen müstahkem Kayseri'], 'I. Haçlı Seferi baskısı yüzünden batıdaki İznik elden çıkınca I. Kılıçarslan başkenti İç Anadolu\'nun korunaklı merkezi Konya\'ya nakletmiştir.'),
  ('17 Eylül 1176 tarihinde Sultan II. Kılıçarslan ile Bizans İmparatoru I. Manuel Komnenos arasında gerçekleşen Miryokefalon Savaşı\'nın Anadolu tarihi açısından en kalıcı siyasi sonucu nedir?', 'Bizans\'ın Türkleri Anadolu\'dan çıkarma ümidinin kesin biçimde sona ermesi', ['İstanbul\'un kara surlarının yıkılarak kentin Selçuklu valiliğine bağlanması', 'Ege adalarının tamamının Türkiye Selçuklu donanmasına vergi vermeye başlaması', 'Abbasi Halifeliği makamının Bağdat\'tan alınarak Konya sarayına taşınması'], 'Malazgirt\'in \'yurt açan\' niteliğine karşılık 1176 Miryokefalon Zaferi \'yurt tutan\' savaş olmuş; Bizans savunmaya çekilirken Anadolu kesin Türk vatanı haline gelmiştir.'),
  ('Yaşlanan Sultan II. Kılıçarslan\'ın 1186 yılında ülkeyi on bir oğlu arasında paylaştırması eski Türk devlet geleneğindeki hangi anlayışın Türkiye Selçuklularında da sürdüğünü kanıtlar?', 'Ülke topraklarının hanedan ailesinin ortak mülkü sayılması ilkesinin', ['Saltanatın yalnızca en yaşlı ve bilge hanedan üyesine devredilmesi kuralının', 'Eyalet valilerinin her beş yılda bir halk meclislerince seçilmesi usulünün', 'Fethedilen vilayetlerin komutanlara bağımsız krallık olarak bağışlanmasının'], 'Türk veraset anlayışındaki \'ülke hanedanın ortak malıdır\' geleneğine uyarak ülkeyi 11 melik arasında bölüştüren II. Kılıçarslan, henüz hayattayken oğulları arasında şiddetli taht kavgalarının çıkmasına engel olamamıştır.'),
  ('1207 yılında Venedik ve Kıbrıslı tüccarların kervan yollarını kesmesi üzerine sefere çıkarak Antalya\'yı fetheden ve Türkiye Selçuklularını ilk kez Akdeniz\'e ulaştıran sultan kimdir?', 'I. Gıyaseddin Keyhüsrev', ['Sinop limanını Trabzon Rumlarından alan I. İzzeddin Keykavus', 'Kırım\'ın Suğdak limanına denizaşırı sefer düzenleyen I. Alaeddin Keykubad', 'Erzurum\'daki Saltuklu yönetimine son veren Rükneddin Süleymanşah'], 'İkinci saltanat döneminde (1205-1211) tüccarların şikâyetlerini de dikkate alan I. Gıyaseddin Keyhüsrev, 1207\'de Antalya\'yı fethederek devleti Akdeniz ticaretine açmıştır.'),
  ('Türkiye Selçuklu Devleti\'ne en parlak çağını yaşatan Sultan I. Alaeddin Keykubad\'ın Akdeniz kıyısındaki Kandelor (Kalonoros) Kalesi\'ni fethederek kendi adıyla yeniden imar ettiği liman kenti hangisidir?', 'Alaiye (Alanya)', ['Kilikya sahil şeridinde dış ticarete aracılık eden Ayas (Yumurtalık)', 'Batı Anadolu\'da Küçük Menderes ağzında yükselen Ayasuluk (Selçuk)', 'Teke Yarımadası\'nın batı ucunda gemilere sığınak olan Mekri (Fethiye)'], '1221 yılında Ermeni hâkimi Kir Vart\'tan Kandelor Kalesi\'ni teslim alan I. Alaeddin Keykubad, kenti Alaiye adıyla kışlık başkent ve büyük bir deniz üssü yapmıştır.'),
  ('1230 yılında Erzincan yakınlarında Türkiye Selçukluları ile Celaleddin Harzemşah arasında yapılan Yassıçemen Savaşı\'nın zaferle sonuçlanmasına rağmen uzun vadede Selçuklulara zarar vermesinin nedeni nedir?', 'Moğollarla Anadolu arasındaki tampon Harzemşah gücünün ortadan kalkması', ['Selçuklu hazinesindeki tüm altın stoklarının savaş tazminatı olarak ödenmesi', 'Konya\'daki medrese ve kervansarayların Harzemli askerlerce yakılıp yıkılması', 'Trabzon Rum ordusunun fırsattan yararlanarak Sivas ve Kayseri\'yi işgal etmesi'], 'Celaleddin Harzemşah\'ın Ahlat\'ı tahrip etmesi üzerine yapılan Yassıçemen Savaşı\'nı Selçuklu-Eyyubi ittifakı kazanmışsa da Harzemşah Devleti yıkılınca Anadolu Moğol ordularıyla doğrudan komşu kalmıştır.'),
  ('1240 yılında Güneydoğu ve Orta Anadolu\'da göçebe Türkmenlerin ağır vergiler, otlak darlığı ve yönetim baskısına karşı başlattığı, devletin askeri zaafını Moğollara açıkça gösteren ayaklanma hangisidir?', 'Baba İshak (Babailer) İsyanı', ['Karamanoğullarının Konya\'da başlattığı Cimri (Siyavuş) Ayaklanması', 'Batı Anadolu uçlarında ortaya çıkan Şeyh Bedreddin Hareketi', 'Bozok yaylasında tımar kesintilerine tepki gösteren Bozoklu Celal İsyanı'], 'Baba İlyas ve müridi Baba İshak öncülüğündeki Türkmen isyanı Selçuklu ordularını defalarca yenmiş; ancak güçlükle Kırşehir Malya Ovası\'nda bastırılabilmiş ve Moğolları Anadolu\'ya girmeye cesaretlendirmiştir.'),
  ('1243 yılında Sivas\'ın doğusundaki Kösedağ Savaşı\'nda Baycu Noyan komutasındaki Moğol ordusunun Türkiye Selçuklu ordusunu ağır yenilgiye uğratmasının ardından Anadolu\'da başlayan siyasi süreç aşağıdakilerden hangisidir?', 'Selçuklu sultanlarının İlhanlılara vergi ödeyen bağımlı yöneticilere dönüşmesi', ['Türkiye Selçuklu hanedanının aynı yıl tahttan çekilerek Mısır\'a göç etmesi', 'Bizans İmparatorluğu\'nun Orta Anadolu yaylasını yeniden sınırlarına katması', 'Anadolu\'daki tüm kervan yollarının yüz yıl boyunca ticarete kapatılması'], 'Kösedağ bozgunundan sonra Türkiye Selçuklu Devleti hemen yıkılmamış ancak bağımsızlığını yitirerek 1308\'e kadar Moğol (İlhanlı) tahakkümü ve ağır vergi baskısı altında yaşamıştır.'),
  ('Türkiye Selçuklularının Akdeniz ve Karadeniz ticaret limanlarını ele geçirdikten sonra sultanların unvanları arasına eklenen \'Sultanü\'l-Bahreyn\' ibaresi ne anlama gelmektedir?', 'İki denizin sultanı', ['Doğu ve batı iklimlerinin koruyucusu', 'Kutsal şehirlerin adaletli hizmetkârı', 'Gaza sınırlarının yenilmez başkomutanı'], 'Antalya ve Alanya ile Akdeniz\'e, Sinop ve Samsun ile Karadeniz\'e hâkim olan Türkiye Selçuklu hükümdarları kitabelerde \'Sultanü\'l-Berreyn ve\'l-Bahreyn\' (İki Karanın ve İki Denizin Sultanı) unvanını kullanmıştır.'),
  ('Türkiye Selçuklu merkez teşkilatında devlet işlerinin görüşülüp karara bağlandığı en üst yönetim kuruluna ne ad verilmiştir?', 'Divan-ı Saltanat', ['Yalnızca sınır boylarındaki uç beylerinin toplandığı Kurultay-ı Uç', 'Esnaf loncalarının fiyat tarifelerini belirleyen Meclis-i Ahiyan', 'Medrese müderrislerinin müfredatı tartıştığı Encümen-i Daniş'], 'Büyük Selçuklulardaki Büyük Divan\'ın karşılığı olan Divan-ı Saltanat (Divan-ı Âlâ), vezirin başkanlığında devletin idari, mali, hukuki ve askeri kararlarını alan en yüksek organdır.'),
  ('Türkiye Selçuklu saray teşkilatında hükümdarın yiyeceklerinin hazırlanmasına nezaret eden ve zehirlenme ihtimaline karşı yemekleri sultandan önce tadan görevli kimdir?', 'Çaşnigir', ['Hükümdarın şerbet ve içecek takımlarını koruyan Şarabdâr-ı Hâs', 'Saray ahırlarındaki binek atlarının bakımını yöneten Emir-i Âhur', 'Törenlerde kalabalığı düzenleyip protokole yol açan Emir-i Mahfil'], 'Saray mutfağının (matbah) amiri olan Çaşnigir (Emir-i Çaşnigir), sultanın sofrasına gelen yemeklerin güvenliğinden sorumlu güvenilir bir saray büyüğüydü.'),
  ('Selçuklu hanedanında küçük yaştaki şehzadelerin (meliklerin) taşradaki vilayetlere vali olarak gönderilirken yanlarına verilen, onları devlet yönetimi ve askerlik alanında yetiştiren tecrübeli devlet adamlarına ne denirdi?', 'Atabey', ['Yeni fethedilen toprakların tahririni yapan Muharrir', 'Donanma üslerinde kalyon yapımını yöneten Kaptan-ı Derya', 'Medreselerde müderrislere yardımcı olan kıdemli Danişmend'], 'Büyük Selçuklulardan devralınan Atabeylik kurumu, meliklerin idari ve askeri tecrübe kazanmasını sağlamış; ancak merkezi otorite zayıfladığında bazı atabeyler nüfuzlarını artırmıştır.'),
  ('Türkiye Selçuklu taşra idaresinde büyük vilayetlerin ve şehirlerin askeri güvenliğinden sorumlu olan, savaş zamanında bölgesindeki askerlerle orduya katılan komutana ne ad verilmiştir?', 'Subaşı', ['Çarşı esnafının ürettiği malların kalitesini ölçen Ehlihibre', 'Vakıf arazilerinin kiralarını toplayıp şifahaneye aktaran Mütevelli', 'Kervansaraylarda konaklayan yolcuların hayvanlarını nallayan Baytar'], 'Taşra şehirlerinde askeri vali ve garnizon komutanı niteliğindeki Subaşı (Sübaşı / Serleşker), hem asayişi korur hem de seferde vilayet kuvvetlerine komuta ederdi.'),
  ('Türkiye Selçuklu ordusunun çekirdeğini oluşturan, farklı milletlerden küçük yaşta alınıp saray okullarında İslami ve askeri eğitimle yetiştirilen, üç ayda bir devletten maaş (bistegânî) alan daimi birlik hangisidir?', 'Gulâmân-ı Saray', ['Yalnızca savaş mevsiminde ganimet payı karşılığı toplanan Akıncılar', 'Toprak gelirleriyle atlı asker besleyen taşradaki İkta Sipahileri', 'Bizans sınırındaki yaylalarda çadırlarıyla yaşayan Göçebe Türkmenler'], 'Hükümdarın şahsına sıkı sadakatle bağlı olan Gulâmân-ı Saray (Hassa askerleri), her an savaşa hazır profesyonel merkez ordusuydu ve nakit maaş alırdı.'),
  ('Türkiye Selçuklu ordusunun sayıca en kalabalık kesimini oluşturan \'İkta (Tımar) Askerleri\'nin hazineden nakit maaş almadan donanımlı biçimde sefere katılmaları nasıl sağlanmıştır?', 'Kendilerine tahsis edilen mirî arazi vergileriyle geçinip atlı asker (cebelü) beslemeleriyle', ['Savaşta ele geçirdikleri kalelerin tapusunu aile mülkü olarak satabilmeleriyle', 'Şehirlerdeki yabancı tüccarlardan kendi adlarına özel yol vergisi toplamalarıyla', 'Barış dönemlerinde saray darphanesinde ücretli maden işçisi olarak çalışmalarıyla'], 'İkta sisteminde devlet, hazineden para çıkarmaksızın toprağın vergi gelirini komutan ve sipahilere bırakır; onlar da gelirle orantılı sayıda tam teçhizatlı atlı asker yetiştirirdi.'),
  ('Türkiye Selçuklu toprak düzeninde mülkiyeti devlete (beytülmale) ait olan ve ülkedeki ekilebilir arazilerin büyük çoğunluğunu kapsayan toprak statüsü hangisidir?', 'Mirî arazi', ['Sahiplerinin dilediği gibi satıp miras bırakabildiği Mülk arazi', 'Geliri cami, medrese ve darüşşifalara ayrılan Vakıf arazisi', 'Kimsenin kullanımında olmayan taşlık ve çorak Mevat arazi'], 'Selçuklu arazi rejiminin temelini mülkiyeti devlete, işletme hakkı (tasarrufu) köylüye, vergi geliri ise has ve ikta sahiplerine ait olan \'mirî arazi\' oluşturur.'),
  ('Selçuklu toprak sisteminde doğrudan hükümdara ve hanedan mensuplarına ayrılan, geliri doğrudan saltanat hazinesine (Hazine-i Hâssa) aktarılan verimli topraklara ne ad verilirdi?', 'Has arazi', ['Yoksul öğrencilerin barınması için ayrılan İmarethane toprağı', 'Köylülerin hayvanlarını ortaklaşa otlattığı Koru ve Mera alanı', 'Gayrimüslim çiftçilerin mülkiyetinde bulunan Haracî bahçeler'], 'Mirî toprakların en yüksek gelir getiren bölümleri sultan ve ailesinin giderleri ile merkez ordusunun finansmanı için \'Has\' statüsünde ayrılırdı.'),
  ('Türkiye Selçuklu hukuk sisteminde İslam fıkhına dayanan evlenme, boşanma, miras ve ticaret davalarına bakan şer\'i mahkemelerin en üst yöneticisi kimdir?', 'Kadıü\'l-Kudât', ['Ordu mensuplarının disiplin suçlarına bakan Kadıasker', 'Devlet düzenine karşı işlenen siyasi suçları yargılayan Emir-i Dâd', 'Çarşı ve pazardaki eksik tartı cezalarını kesen Muhtesip'], 'Başkent Konya\'da oturan ve tüm vilayet kadılarının atama ile denetiminden sorumlu olan şer\'i yargı başkanına Kadıü\'l-Kudât denilirdi.'),
  ('Türkiye Selçuklu sultanlarının haftanın belirli günlerinde bizzat başkanlık ederek halkın memurlardan, valilerden ve kadılardan olan şikâyetlerini dinlediği yüksek adalet divanı hangisidir?', 'Divan-ı Mezâlim', ['Askeri sefer planlarının hazırlandığı Divan-ı Harb', 'Posta ve istihbarat raporlarının okunduğu Divan-ı Berid', 'Tahrir defterlerinin temize çekildiği Divan-ı Pervane'], 'Hükümdarın en yüce görevi adalet dağıtmak sayıldığından, güçlü kişiler ve devlet görevlileri hakkındaki şikâyetler doğrudan sultanın başkanlık ettiği Divan-ı Mezâlim\'de karara bağlanırdı.'),
  ('Türkiye Selçuklu Devleti\'nde vergi sisteminin temel kalemlerinden olan \'öşür\' ve \'haraç\' vergileri aşağıdakilerin hangisinde nitelikleri bakımından doğru karşılaştırılmıştır?', 'Öşür Müslüman üreticiden, haraç ise gayrimüslim tebaadan alınan şer\'i toprak/ürün vergisidir', ['Öşür şehirli esnaftan gümüş olarak, haraç ise yalnız göçebe çobanlardan koyun olarak alınır', 'Öşür barış zamanında toplanırken, haraç yalnızca olağanüstü savaş yıllarında salınır', 'Öşür vakıf arazilerine verilirken, haraç doğrudan yabancı elçilerin masraflarına harcanır'], 'İslam mali hukukuna uygun olarak Selçuklularda Müslüman çiftçilerden ürünün onda biri oranında \'öşür\', gayrimüslim çiftçilerden ise \'haraç\' (harac-ı mukaseme / muvazzaf) vergisi tahsil edilirdi.'),
  ('Selçuklu egemenliği altında yaşayan gayrimüslim erkek nüfustan, can ve mal güvenliklerinin devletçe korunması ve askerlik hizmetinden muaf tutulmaları karşılığında alınan şer\'i vergi hangisidir?', 'Cizye', ['Pazar yerlerinde satılan ticari mallardan kesilen Bac', 'Yaylak ve kışlaklardaki koyun sürülerinden alınan Ağnam', 'Olağanüstü kıtlık ve sefer hallerinde toplanan Avarız'], 'Zımmi hukukuna tabi sağlıklı gayrimüslim erkeklerden gelir düzeylerine göre yılda bir kez alınan baş vergisine \'cizye\' denir; kadınlar, çocuklar, yaşlılar ve din adamları bundan muaftı.'),
  ('Selçuklu taşra ve şehir idaresinde çarşı-pazar esnafını denetleyen, ölçü ve tartı hilelerini engelleyen, gıda temizliğini ve fiyat (narh) kurallarını kontrol eden görevli kimdir?', 'Muhtesip', ['Askeri iktaların sınır anlaşmazlıklarını çözen Pervaneci', 'Saray kütüphanesindeki el yazmalarını çoğaltan Müstensih', 'Sınır kalelerindeki silah depolarını teslim alan Cebeci'], 'İslam şehirlerindeki \'hisbe\' teşkilatının başı olan Muhtesip, kadının denetiminde bugünkü belediye zabıtası gibi pazar ahlakını, tartıları ve halk sağlığını kontrol ederdi.'),
  ('Selçuklu saray teşkilatında hükümdarın av partilerini düzenleyen, av köpekleri ile doğan-şahin gibi yırtıcı av kuşlarının eğitiminden sorumlu olan saray büyüğü hangisidir?', 'Emir-i Şikâr', ['Saltanat sancaklarını savaşta koruyan Emir-i Alem', 'Saray mutfağının erzak alımını yapan Havayiç Saları', 'Devlet protokolünde elçileri karşılayan Emir-i Mahfil'], 'Türk devletlerinde sürek avları aynı zamanda bir savaş tatbikatı olduğundan av organizasyonunu yürüten Emir-i Şikâr sarayın önemli emirlerinden biriydi.'),
  ('1308 yılında İlhanlıların atadığı valilerin gölgesinde kalan son Türkiye Selçuklu Sultanı II. Mesud\'un Kayseri\'de vefat etmesiyle Anadolu siyasi haritasında hangi dönem resmen kapanmıştır?', 'Türkiye Selçuklu Devleti\'nin hukuki ve hanedan varlığı', ['Anadolu\'daki ikinci dönem Türkmen beyliklerinin kuruluş süreci', 'İlhanlı Devleti\'nin Orta Anadolu üzerindeki askeri ve mali nüfuzu', 'Karadeniz limanlarındaki Ceneviz ve Venedik ticaret kolonileri'], 'Kösedağ\'dan (1243) sonra zayıflayan Türkiye Selçuklu Devleti, 1308 yılında Sultan II. Mesud\'un ölümüyle tarihe karışmış; Anadolu\'da Beylikler Dönemi ve İlhanlı valiler devri sürmüştür.'),
  ('Türkiye Selçuklu sarayında hükümdarın atlarının yetiştirildiği, eğitildiği ve sefer için hazır tutulduğu saray ahırlarının (\'İstabl-ı Âmire\') başındaki emir kimdir?', 'Emir-i Âhur', ['Sarayın şerbet ve meşrubat mutfağını yöneten Şarabdâr', 'Elçilerin konaklama giderlerini karşılayan Mihmandâr', 'Hükümdarın özel yazı takımlarını taşıyan Devâtdâr'], 'Süvari ağırlıklı bir orduya sahip olan Selçuklularda sultanın ve saray muhafızlarının binlerce seçkin atından sorumlu Emir-i Âhur (İmrahor), protokolde yüksek mevkili bir komutandı.'),
  ('Konya ile Aksaray arasındaki ana ticaret güzergâhında 1229 yılında I. Alaeddin Keykubad tarafından yaptırılan ve avlusundaki köşk mescidiyle anıtsal han mimarisinin zirvesi sayılan yapı hangisidir?', 'Aksaray Sultan Hanı', ['Sivas ile Malatya arasındaki dağ geçidinde yükselen Hekimhan Kervansarayı', 'Antalya limanından kuzeye çıkan tüccarları ağırlayan Kırkgöz Hanı', 'Beyşehir Gölü kıyısında yazlık saray yolu üzerine kurulan Kızılören Hanı'], 'Mimar Muhammed bin Havlan el-Dımaşkî\'nin eseri olan Aksaray Sultan Hanı, 4500 metrekareyi aşan alanı ve avlu ortasındaki kemerli köşk mescidiyle en görkemli Selçuklu kervansarayıdır.'),
  ('Kervan yolları üzerinde yaklaşık otuz-kırk kilometrelik (dokuz saatlik deve yürüyüşü) aralıklarla hanların sıralanmasında gözetilen temel lojistik ölçü nedir?', 'Yüklü bir kervanın gün batmadan güvenli menzile ulaşabileceği bir günlük yürüyüş mesafesi', ['Posta güvercinlerinin dinlenmeden tek seferde uçabileceği en uzak görüş menzili', 'İkta sipahilerinin vergi toplamak üzere sorumlu tutulduğu köy sınırı genişliği', 'Su kemerlerinin yer çekimi eğimiyle tatlı su taşıyabildiği azami boru uzunluğu'], 'Selçuklu kervansarayları bir deve kervanının sabah yola çıkıp hava kararmadan eşkıya ve soğuk tehlikesine yakalanmadan varabileceği \'bir menzil\' (yaklaşık 35-40 km) mesafeye göre planlanmıştır.'),
  ('Vakfiyelere göre Selçuklu kervansaraylarında konaklayan yerli veya yabancı, Müslüman ya da gayrimüslim ayrımı yapılmaksızın tüm yolculara kaç gün boyunca yemek, hayvan yemi ve bakım hizmeti ücretsiz sunulmuştur?', 'Üç gün', ['Yalnızca fırtınalı kış gecelerinde geçerli olmak üzere bir gece', 'Yerli tüccarlara yedi gün, yabancı ülke tüccarlarına ise on beş gün', 'Gümrük vergisi makbuzunu ibraz eden kervan sahiplerine bir ay'], 'Karatay Han ve Sultan Han vakfiyelerinde zengin-fakir, hür-köle, Müslüman-gayrimüslim ayrımı gözetilmeksizin her yolcunun üç gün ücretsiz ağırlanacağı, hatta yırtık ayakkabısının onarılıp hayvanının nallanacağı şart koşulmuştur.'),
  ('Eşkıya baskınına, korsan saldırısına veya yol güvenliği zaafına uğrayarak malları yağmalanan tüccarların zararının devlet hazinesinden karşılanması iktisat tarihinde nasıl nitelendirilir?', 'Dünya ticaret tarihindeki ilk devlet sigortası uygulaması', ['Yabancı tüccarlara tanınan süresiz gümrük ve pazar vergisi muafiyeti', 'Kervansaray vakıflarının özel tefecilere devredildiği iltizam sözleşmesi', 'Deniz aşırı kolonilerde kurulan ortak sermayeli anonim banka ortaklığı'], 'I. Alaeddin Keykubad ve öncesinde uygulanan bu sistemde, Selçuklu sınırları içinde malı çalınan veya korsanlarca gasp edilen tüccarın zararı devlet hazinesinden ödenip ardından suçlular cezalandırılmıştır.'),
  ('Kırşehir\'e yerleşerek dericilik (debbağlık) mesleğini örgütleyen, esnaf arasında iş ahlakı ve dayanışma ilkelerini kurumsallaştırarak Ahilik teşkilatını kuran mutasavvıf ve bilgin kimdir?', 'Ahi Evran', ['Konya\'da hadis ve tasavvuf dersleri okutan Sadreddin Konevî', 'Sulucakarahöyük dergâhında Türkmenleri irşat eden Hacı Bektaş-ı Velî', 'Taptuk Emre\'nin dergâhında yetişip ilahiler söyleyen Yunus Emre'], 'Asıl adı Şeyh Nasîrüddin Mahmud el-Hoyî olan Ahi Evran, 32 esnaf kolunun piri kabul edilmiş ve Kayseri ile Kırşehir\'de Ahilik teşkilatını kurmuştur.'),
  ('Ahi Evran\'ın eşi Fatma Bacı (Kadıncık Ana) öncülüğünde kurulan, kimsesiz kızları koruyan, kadınlara çadır dokumacılığı ile örgücülük öğreten ve gerektiğinde şehir savunmasına katılan kadın teşkilatı hangisidir?', 'Bâcıyân-ı Rûm', ['Sınır kalelerinde atlı akınlara çıkan Gaziyân-ı Rûm', 'Tekke ve zaviyelerde halkı aydınlatan Abdâlân-ı Rûm', 'Genç esnaf çıraklarını bir araya getiren Fityân-ı Rûm'], 'Âşıkpaşazâde\'nin Anadolu\'daki dört sosyal zümreden biri olarak saydığı \'Bâcıyân-ı Rûm\' (Anadolu Bacıları), dünyanın bilinen en erken örgütlü kadın meslek ve dayanışma birliklerinden biridir.'),
  ('Halk dilinde \'pabucun dama atılması\' deyiminin doğmasına kaynaklık eden Ahi denetim uygulamasının çarşı düzenindeki gerçek işlevi neydi?', 'Kusurlu veya hileli ayakkabı üreten ustanın malını çatısına atıp esnaflıktan men ederek tüketiciyi korumak', ['Bayram günlerinde yoksul çocuklara dağıtılacak yeni ayakkabıları dükkân saçaklarında sergilemek', 'Vergi borcunu erken ödeyen başarılı deri ustalarını ödüllendirmek için çatılarına flama asmak', 'Ustalığa yükselen kalfanın ilk diktiği ayakkabıyı uğur getirmesi amacıyla kervansaray kubbesine koymak'], 'Ahi Yiğitbaşı ve Ehl-i Hibre heyeti şikâyet edilen çürük ayakkabıyı inceler, kusurlu bulursa ibret olsun diye ustanın pabucunu dükkân damına atıp dükkânı mühürlerdi; halk artık o ustadan alışveriş etmezdi.'),
  ('Fiyat istikrarını korumak, karaborsacılığı ve haksız kazancı önlemek amacıyla kadı, muhtesip ve Ahi temsilcilerinin birlikte temel tüketim malları için azami satış fiyatı belirlemesine ne ad verilirdi?', 'Narh koyma', ['İhtiyaca göre dükkân açma sayısını sınırlayan Gedik verme', 'Devlet adına gümrük gelirlerini peşin kiralayan İltizam usulü', 'Sikke içindeki gümüş oranını düşürerek yapılan Tağşiş işlemi'], 'Üretici maliyetine makul bir kâr payı eklenerek belirlenen tavan fiyat uygulamasına \'narh\' denir; narhın üzerinde mal satan esnaf ağır biçimde cezalandırılırdı.'),
  ('Kırşehir merkezde 1272 yılında Kırşehir Emiri Nureddin Cibril bin Cacabey tarafından yaptırılan \'Cacabey Medresesi\', köşe kulelerindeki roket/sütun biçimleri ve kubbe altındaki kuyusuyla hangi bilim dalının rasathane-okulu olarak ün kazanmıştır?', 'Astronomi', ['Deniz haritacılığı ve açık okyanus gemiciliği', 'Maden cevherlerinin ayrıştırıldığı simya ve metalürji', 'Bitki köklerinden boya elde edilen dokuma kimyası'], 'Orta kubbesindeki aydınlık açıklığının tam altında bulunan su kuyusuna yansıyan yıldızların gündüz ve gece gözlemlendiği Kırşehir Cacabey Medresesi, dünyanın ilk uygulamalı astronomi yüksekokullarından biridir.'),
  ('Horasan\'ın Belh şehrinden ailesiyle göç edip I. Alaeddin Keykubad\'ın davetiyle Konya\'ya yerleşen Bahaeddin Veled\'in oğlu olup evrensel insan sevgisi ve hoşgörüyü Farsça beyitlerle işleyen büyük mutasavvıf kimdir?', 'Mevlânâ Celâleddin-i Rûmî', ['Vahdet-i vücûd felsefesini Endülüs\'ten Malatya ve Konya\'ya taşıyan İbnü\'l-Arabî', 'Halkın konuştuğu sade Türkçeyle ilahi aşkı şiirleştiren derviş Yunus Emre', 'Fütüvvet teşkilatını esnaf loncalarıyla birleştiren Şeyh Ahi Evran'], '1207\'de Belh\'te doğup 1273\'te Konya\'da (\'Şeb-i Arûs\') vefat eden Mevlânâ Celâleddin-i Rûmî, \'Mesnevî\', \'Dîvân-ı Kebîr\', \'Fîhi Mâ Fîh\' ve \'Mecâlis-i Seb\'a\' adlı eserleriyle dünya düşünce tarihine damga vurmuştur.'),
  ('Moğol istilasının Anadolu\'da yarattığı yıkım, korku ve toplumsal çözülme ortamında Mevlânâ, Hacı Bektaş-ı Velî ve Yunus Emre gibi gönül erlerinin üstlendiği en hayati sosyal işlev ne olmuştur?', 'Umutsuzluğa düşen halka manevi direnç, birlik ruhu ve toplumsal barış aşılamaları', ['Paralı askerlerden oluşan gizli ordular kurarak Moğol kalelerini kuşatmaları', 'Halkı Anadolu\'yu terk ederek topluca Kuzey Afrika kıyılarına göçe çağırmaları', 'Şehirlerdeki medrese eğitimini kapatıp yalnızca sözlü geleneği zorunlu kılmaları'], 'Siyasi otoritenin çöktüğü 13. yüzyılın ikinci yarısında Anadolu erenleri ve mutasavvıfları, kurdukları dergâhlarla halkın manevi sığınağı olmuş ve toplumsal bütünlüğün dağılmasını önlemişlerdir.'),
  ('Beyşehir Gölü\'nün güneybatı kıyısında Sultan I. Alaeddin Keykubad tarafından yaptırılan ve kazılarda duvarlarını kaplayan sekiz köşeli yıldız ile haç biçimli figürlü çinileriyle bilim dünyasını büyüleyen yazlık saray hangisidir?', 'Kubadâbâd Sarayı', ['Kayseri şeker gölü kenarında kurulan Keykubâdiye Köşkü', 'Konya iç kalesi höyüğü üzerinde yükselen Kılıçarslan Köşkü', 'Alanya yarımadasının zirvesindeki İç Kale Saltanat Sarayı'], '1226-1236 yıllarında inşa edilen Kubadâbâd Sarayı külliyesi; av sahneleri, bağdaş kurmuş saraylılar, çift başlı kartal, sfenks ve siren tasvirli sıraltı-lüster çinileriyle Selçuklu saray sanatının en zengin hazinesidir.'),
  ('Alanya limanını ve tersanesini denizden gelecek saldırılara karşı korumak amacıyla 1226 yılında Halep\'ten davet edilen Mimar Ebu Ali Reha el-Kettânî\'ye yaptırılan sekizgen planlı anıtsal savunma yapısı hangisidir?', 'Kızılkule', ['Sinop yarımadasının en dar berzahını tutan Hızırbey Burcu', 'Antalya liman girişinde zincir gerilen Hıdırlık Kulesi', 'Mersin Silifke sahilinde adacık üzerine kurulan Kızkalesi'], 'Üst katlarında kesme taş yerine kırmızı tuğla kullanıldığı için \'Kızılkule\' adını alan 33 metre yüksekliğindeki beş katlı sekizgen burç, Orta Çağ askeri mimarisinin kusursuz örneklerindendir.'),
  ('Büyük şehirlerin ticari ve sosyal dokusunu betimleyen kaynaklarda, her meslek grubunun (bakırcılar, saraçlar, kuyumcular, attarlar) şehir çarşısında kendine ait ayrı bir sokakta (arasta/suk) toplanmasının temel faydası nedir?', 'Kalite ile fiyat denetimini kolaylaştırmak ve meslek içi haksız rekabeti önlemek', ['Esnaf ailelerinin başka meslek sahipleriyle kız alıp vermesini yasaklamak', 'Şehir dışından gelen köylülerin çarşı merkezine girmesini engellemek', 'Gece bekçilerinin sayısını azaltarak belediye vergilerini düşürmek'], 'Selçuklu çarşılarında aynı iş kolundaki ustaların aynı sokakta bulunması, hem Ahi Yiğitbaşının ve Muhtesibin hammadde dağıtımı ile kalite kontrolünü kolaylaştırmış hem de müşteriye karşılaştırma imkânı sunmuştur.'),
  ('Deri işleme (debbağlık), boyacılık ve sabun imalatı gibi kötü koku çıkaran ve bol suya ihtiyaç duyan iş kollarının şehir merkezindeki ulu cami çevresi yerine sur dışındaki akarsu kenarlarına yerleştirilmesi neyi gösterir?', 'Çevre sağlığı ve kentsel temizlik ilkelerini gözeten bilinçli bir şehircilik planlamasını', ['Dericilikle uğraşan Ahi ustalarının şehir meclislerine girmesinin yasaklandığını', 'Sur içindeki arazilerin tamamının yabancı tüccar konaklarına ayrıldığını', 'Zanaatkârların vergi ödememek için resmi denetim sınırının dışına kaçtığını'], 'Kırşehir, Kayseri ve Konya gibi Selçuklu kentlerinde debbağhaneler (tabakhaneler) daima hâkim rüzgârın ters yönünde ve akarsuyun şehirden çıktığı alt kotta kurularak halk sağlığı korunmuştur.'),
  ('Anadolu kervansaraylarının kalın kesme taş dış duvarları, mazgal pencereleri, payanda kuleleri ve demir kaplamalı tek giriş kapısıyla dıştan bir kale görünümü taşımasının başlıca nedeni nedir?', 'İçindeki değerli ticari malları ve yolcuları eşkıya veya düşman akınlarına karşı korumak', ['Barış zamanında kervansarayların eyalet hapishanesi olarak kullanılmasını sağlamak', 'İçeride konaklayan yabancı tüccarların dışarıdaki halkla konuşmasını engellemek', 'Sert rüzgârlarda binanın ahşap çatısının uçmasını ağırlık kuleleriyle önlemek'], 'İslami dönemdeki sınır karakolu \'ribat\' mimarisinden gelişen Anadolu Selçuklu kervansarayları (Sultan hanları), ıssız menzillerde tam güvenlik sunan tahkimli birer ticaret kalesi olarak tasarlanmıştır.'),
  ('Selçuklu taş işçiliğinde cami, medrese ve kervansarayların tüm görkemiyle sokağa ya da yola açılan, sarkıtlı \'mukarnas\' kavsaralar ve geometrik şeritlerle bezenmiş anıtsal giriş bölümüne ne ad verilir?', 'Taç kapı', ['Kubbe ağırlığını kare duvarlara aktaran üçgen geçiş öğesi Pandantif', 'Avlu etrafında sütun ve kemerlerle örtülü gölgelik galeri Revak', 'Üç tarafı kapalı olup avluya yüksek bir kemerle açılan salon Eyvan'], 'Dış cepheleri oldukça sade ve masif olan Selçuklu yapılarında bütün bezeme enerjisi girişteki anıtsal \'taç kapı\'da (portal) toplanarak yapıya giren insanda hayranlık ve saygı uyandırılmıştır.'),
  ('Çankırı\'da 1235 yılında I. Alaeddin Keykubad\'ın emirlerinden Cemaleddin Ferruh tarafından yaptırılan \'Taş Mescit ve Darüşşifası\'nda taş üzerine işlenmiş birbirine dolanmış iki yılan ve kupa-yılan kabartması bugün neyin sembolü olmuştur?', 'Tıp ve eczacılık mesleğinin simgesi', ['Deniz ticaret sigortacılığının arması', 'Astronomi ve takvim hesaplamalarının işareti', 'Mimar ve taş ustaları loncasının mührü'], 'Çankırı Cemaleddin Ferruh Darüşşifası\'nda bulunan birbirine sarılı çifte yılan ve kâseden su içen yılan kabartmaları, Selçuklu şifahanelerinden günümüz Türk tıbbına miras kalan semboldür.'),
  ('Mevlânâ\'nın oğlu Sultan Veled\'in babasının vefatından sonra dağınık haldeki sohbet ve sema halkalarını belli adab, vakıf ve dergâh kuralları çerçevesinde birleştirerek kurumsallaştırdığı tasavvuf yolu hangisidir?', 'Mevlevîlik', ['Orta Asya bozkırlarında Ahmet Yesevî\'nin başlattığı Yesevîlik', 'Bağdat merkezli gelişip Anadolu\'ya yayılan Kâdirîlik', 'Şeyh Safiyyüddin tarafından Erdebil\'de kurulan Safevîlik'], 'Mevlânâ sağlığında resmi bir tarikat kurmamış; vefatından sonra Çelebi Hüsameddin ve özellikle oğlu Sultan Veled Mevlevîliği kuralları, müziği ve dergâh teşkilatıyla sistemleştirmiştir.'),
  ('Selçuklu medreselerinde müderrislerin, öğrencilerin (danişmendlerin), kütüphanecinin ve bina görevlilerinin maaşları ile yemek-aydınlatma giderlerinin devlet bütçesinden değil \'vakıf gelirlerinden\' karşılanmasının eğitime sağladığı en önemli güvence nedir?', 'Siyasi sarsıntı ve taht kavgalarından etkilenmeden bilimsel eğitimin kesintisiz ve özerk sürmesi', ['Medrese öğrencilerinin mezun olduktan sonra ömür boyu vakıf tarlalarında çalışma zorunluluğu', 'Müderrislerin okutacağı kitapların her yıl vakıf kiracıları tarafından oylanarak seçilmesi', 'Devletin eğitim kurumları üzerinde hiçbir hukuki denetim hakkının bulunmaması'], 'Hanlar, dükkânlar, hamamlar ve tarım arazilerinin gelirleri vakfiyeyle medreselere bağlandığından, merkezi hazine darlığa düşse bile eğitim ve araştırma faaliyetleri kendi vakıf kaynaklarıyla sürmüştür.'),
  ('13. yüzyıl başlarında Muhyiddin İbnü\'l-Arabî, Necmeddin Râzî (Dâye), Evhadüddin Kirmânî ve Bahaeddin Veled gibi İslam dünyasının en büyük bilginlerinin Anadolu\'ya akın ederek Konya, Kayseri ve Malatya\'ya yerleşmelerinin tarihsel nedeni nedir?', 'Türkistan ve İran\'ı kasıp kavuran Moğol istilası karşısında Türkiye Selçuklularının güvenli ve âlim dostu bir sığınak olması', ['Abbasi Halifesi\'nin Bağdat ve Şam\'daki bütün medreseleri süresiz olarak kapatması', 'Bizans üniversitelerindeki antik felsefe el yazmalarını ele geçirmek için görevlendirilmeleri', 'Selçuklu sultanlarının her yabancı bilgine bir vilayetin vergi gelirini bağışlaması'], 'Cengiz Han ordularının Maveraünnehir ve Horasan\'ı yakıp yıkması üzerine İslam dünyasının seçkin âlim ve sanatkârları, I. İzzeddin Keykavus ve I. Alaeddin Keykubad\'ın istikrarlı ve cömert himayesindeki Anadolu\'ya sığınarak kültürel Rönesans yaratmışlardır.'),
  ('Selçuklu darüşşifalarında hastaların tedavisinin yanı sıra vefat eden yoksul hastaların kefen ve defin masraflarının bile vakfiyede karşılığının ayrılmış olması hangi medeniyet anlayışını yansıtır?', 'İnsana doğumundan ölüm sonrasına dek onurunu incitmeden hizmet eden şefkat ve sosyal devlet/vakıf bilincini', ['Bulaşıcı hastalıklardan ölenlerin şehir dışına çıkarılması için ailelerden ceza kesildiğini', 'Yalnızca kimsesiz yabancıların şifahanelerde yataklı tedaviye kabul edildiğini', 'Hekimlerin başarısız olduğu her vaka için kendi maaşlarından tazminat ödediğini'], 'Kayseri, Sivas ve Amasya darüşşifalarının vakfiyelerinde hastaya şefkatle hitap edilmesi, ilaçların ücretsiz verilmesi ve vefat halinde teçhiz-tekfin işlemlerinin vakıfça üstlenilmesi sosyal dayanışmanın zirvesidir.'),
  ('Sultan I. Alaeddin Keykubad\'ın eşi ve II. Gıyaseddin Keyhüsrev\'in annesi olan \'Mahperi Huand (Hunat) Hatun\'un Kayseri merkezde cami, medrese, hamam ve kümbetten oluşan büyük bir külliye ile çok sayıda kervansaray yaptırması neyi gösterir?', 'Selçuklu hanedan kadınlarının geniş mülk gelirleriyle kentsel imar ve hayır hayatında öncü rol üstlendiğini', ['Kadınların yalnızca kendi türbelerini yaptırabildiğini, eğitim kurumu açamadığını', 'Kayseri şehrinin yönetim yetkisinin tümüyle valide sultanlara devredildiğini', 'Devlet bütçesi tükendiği için kervansarayların halka zorunlu vergiyle yaptırıldığını'], 'Gevher Nesibe Sultan, Mama Hatun, Turan Melek ve Mahperi Huand Hatun gibi Türk-İslam hanedan kadınları, kurdukları dev külliyeler ve kervansaraylarla (Pazar Hatun Hanı vb.) Anadolu\'nun imarına büyük katkı sunmuşlardır.'),
  ('Selçuklu çini ustalarının kervansaray, cami ve medrese duvarlarında firuze (turkuaz) ve kobalt mavisi renklerini ağırlıklı olarak tercih etmelerinin estetik ve kültürel kökeni nedir?', 'Türk kültüründe gökyüzünü, sonsuzluğu ve manevi huzuru simgeleyen gök rengi (turkuaz) tutkusu', ['Anadolu\'da kırmızı, sarı veya yeşil sır elde edecek maden oksitlerinin hiç bulunmaması', 'Yalnızca mavi renkli çinilerin kış soğuğunda çatlamadan duvar yüzeyinde kalabilmesi', 'Bizans kiliselerindeki altın mozaikleri taklit etmek için mavi cam kullanılması'], 'Batı dillerine bile \'Türk mavisi\' (Turquoise / Turkuaz) adıyla geçen firuze rengi, Gök Tanrı ve Türk kozmolojisinden İslam mimarisinin sonsuzluk estetiğine taşınan milli bir renk kimliğidir.'),
  ('Antalya\'da Sultan I. Alaeddin Keykubad döneminde eski bir yapı kalıntısı üzerine yükseltilen ve sekiz yarım silindirik dilimli tuğla gövdesiyle kentin sembolü haline gelen eser hangisidir?', 'Yivli Minare', ['Konya Sahip Ata Külliyesi\'ndeki tek şerefeli İnce Minare', 'Aksaray merkezde eğik duruşuyla tanınan Kızıl Minare', 'Sivas Ulu Camii avlusunda yükselen kalın tuğla Eğri Minare'], 'Antalya\'nın fethinden sonra I. Alaeddin Keykubad devrinde inşa edilen firuze çini kuşaklı ve sekiz yivli tuğla gövdeli \'Yivli Minare\', kentin Türk-İslam mührü haline gelmiştir.'),
  ('Fütüvvet ve Ahilik anlayışında bir Ahi\'nin \'üç şeyi açık, üç şeyi kapalı\' olması öğütlenir; açık olması gerekenler \'eli, kapısı ve sofrası\' iken kapalı olması gereken üç şey nedir?', 'Gözü (harama), dili (yalan ve dedikoduya), beli', ['Dükkân kasası, mesleki üretim sırları ve ticaret ortaklığı defterleri', 'Şehir surlarının kapıları, silah depoları ve vakıf tahıl ambarları', 'Yabancılara karşı evi, komşu esnafa karşı tartısı ve pazara karşı fiyatı'], 'Ahiliğin temel ahlak düsturu cömertlik ve konukseverlikte \'elini, kapısını, sofrasını açık tutmak\'; nefis terbiyesinde ise \'gözünü, dilini ve belini bağlı (kapalı) tutmak\'tır.'),
  ('Selçuklu dönemi Anadolu şehirlerinde Müslüman Türklerle birlikte Rum, Ermeni, Süryani ve Yahudi mahallelerinin ticaret hayatında ortak lonca ve pazar ilişkileri kurabilmesi hangi hukuki ve sosyal iklime dayanmıştır?', 'Din ve vicdan hürriyeti tanıyan hoşgörülü vakıf-pazar düzenine', ['Gayrimüslim zanaatkârların vergi ve yargı denetiminden tamamen muaf olmasına', 'Şehirlerdeki tüm ibadethanelerin ortak tek bir ruhban meclisince yönetilmesine', 'Yerli ahalinin ticaret yapabilmek için Türkçe soyadı alma zorunluluğuna'], 'Mevlânâ\'nın cenazesinde Müslümanlarla birlikte Hristiyan ve Yahudilerin de kendi kutsal kitaplarını okuyarak ağlaması, Selçuklu Konya\'sındaki toplumsal barış ve birlikte yaşama kültürünün en çarpıcı tanıklığıdır.'),
  ('Sivas\'tan başlayıp Malatya ve Elbistan üzerinden Halep\'e, diğer koldan Erzincan ve Erzurum üzerinden Tebriz\'e uzanan doğu-batı ve kuzey-güney kervan ağlarının kavşak noktaları arasında hangi üç İç Anadolu şehri başı çekmiştir?', 'Konya, Kayseri ve Sivas', ['Bilecik, Kütahya ve Balıkesir', 'Çankırı, Kastamonu ve Bolu', 'Muğla, Denizli ve Aydın'], 'Türkiye Selçuklu ticaret omurgasının altın üçgenini başkent Konya, büyük ordugâh ve panayır kenti Kayseri ile dört yönlü transit ticaret metropolü Sivas oluşturmuştur.'),
  ('Fütüvvetnamelerde ve Ahi geleneğinde meslek sahibinin ürettiği malın üzerine kendi damgasını vurması veya hangi atölyeden çıktığının bilinmesi tüketici açısından hangi işlevi görmüştür?', 'Ürün kalitesinde şeffaf sorumluluk ve garanti güvencesi oluşturmayı', ['Yabancı şehirlerden gelen malların çarşıda satılmasını engellemeyi', 'Ustanın ödeyeceği cizye vergisinin mal sayısına göre artırılmasını', 'Müşterinin aldığı ürünü ikinci el pazarda satmasının yasaklanmasını'], 'Üretilen deri, bakır, bıçak veya dokumanın hangi ustanın elinden çıktığının belli olması, kusur çıktığında Ahi loncasının anında muhatap bulmasını ve kalite standardının korunmasını sağlamıştır.'),
  ('Selçuklu medreselerinde fıkıh, tefsir, hadis ve kelam gibi \'naklî (dinî) ilimlerin\' yanında tıp, astronomi, matematik, fizik ve felsefe gibi \'aklî (müspet) ilimlerin\' bir arada okutulması nasıl bir sonuç doğurmuştur?', 'Hem kadı ve din adamı hem de hekim, astronom ve mühendis yetiştiren çok yönlü bir aydın sınıfı doğmuştur', ['Din âlimleri ile fen bilginleri arasında medreselerin bölünmesine ve çatışmaya yol açmıştır', 'Öğrencilerin mezuniyet süresinin otuz yıla çıkması yüzünden medreseler boş kalmıştır', 'Aklî ilimler yalnızca gayrimüslim öğrencilere, naklî ilimler ise Müslümanlara ayrılmıştır'], 'Gevher Nesibe (tıp), Cacabey (astronomi), Buruciye (fizik-gökbilim) ile Sırçalı ve İnce Minareli (fıkıh-hadis) medreseleri, Selçuklu yükseköğretiminin din ve doğa bilimlerini bütünleştirdiğini gösterir.'),
  ('Mevlânâ Celâleddin-i Rûmî\'nin 17 Aralık 1273 tarihindeki vefat gününü yas ve ağlama günü değil, \'Şeb-i Arûs\' (Düğün Gecesi) olarak adlandırıp vasiyet etmesinin tasavvufi gerekçesi nedir?', 'Ölümü yok oluş değil, ruhun asıl vatanına ve sevgili olan Allah\'a kavuşma anı görmesi', ['Vefat ettiği gün Konya\'da yeni sultanın tahta çıkış şenliklerinin kutlanması', 'Moğol komutanlarının şehirde yüksek sesle ağıt yakılmasını yasaklamış olması', 'Oğlu Sultan Veled\'in düğün merasiminin aynı akşam dergâhta yapılması'], 'Mevlânâ ölümü maddi kafesten kurtulup ilahi sevgiliye (Yaradan\'a) kavuşma olarak gördüğünden vefat gecesini \'Şeb-i Arûs\' (Düğün/Kavuşma Gecesi) diye nitelendirmiş ve mezarına ağlayarak gelinmemesini istemiştir.'),
  ('13 Mayıs 1277 tarihinde Konya\'yı ele geçirdikten sonra \'Şimdiden gerü divanda, dergâhta, bargâhta, mecliste ve meydanda Türkçeden başka dil konuşulmaya\' fermanını yayımlayan devlet adamı kimdir?', 'Karamanoğlu Mehmed Bey', ['Kütahya merkezli beyliğin kurucusu sayılan Germiyanoğlu Yakup Bey', 'İzmir ve Ege adalarına deniz seferleri düzenleyen Gazi Umur Bey', 'Sivas tahtında tuyuğlarıyla ün kazanan âlim hükümdar Kadı Burhaneddin'], 'Selçuklu bürokrasisindeki Farsça egemenliğine karşı Türkçeyi resmi devlet dili ilan eden Karamanoğlu Mehmed Bey, Türk dil tarihinde bir dönüm noktası başlatmıştır.'),
  ('Karamanoğulları Beyliği\'nin diğer Anadolu beyliklerine kıyasla Osmanlı Devleti\'ne karşı en uzun süre ve en sert biçimde direnmesinin temel meşruiyet iddiası nedir?', 'Başkent Konya\'ya hâkim olup kendisini Selçuklu mirasçısı sayması', ['Abbasi Halifesi\'nin ailesini Karaman kalesinde misafir ediyor olması', 'Akdeniz\'deki Venedik ve Ceneviz donanmalarının tam desteğini alması', 'Orta Asya\'daki Çağatay Hanlığı ile ortak sınır ve orduya sahip olması'], 'Eski Selçuklu başkenti Konya ve çevresinde hüküm süren Karamanoğulları, Türkiye Selçuklu Devleti\'nin doğal varisi olduklarını öne sürerek Osmanlı üstünlüğünü uzun süre reddetmiştir.'),
  ('Kütahya ve çevresinde kurularak Batı Anadolu\'nun en kudretli kara ordularından birine sahip olan ve erken dönemde Bizans\'tan bile yıllık vergi (haraç) alan Türkmen beyliği hangisidir?', 'Germiyanoğulları', ['Çanakkale ve Balıkesir kıyılarında donanma kuran Karesioğulları', 'Sinop tersanesinde Karadeniz ticaret gemileri üreten Pervaneoğulları', 'Çukurova\'da Memlüklerle komşuluk yürüten Ramazanoğulları'], 'Yakup Bey döneminde zirveye ulaşan Kütahya merkezli Germiyanoğulları, Batı Anadolu\'daki diğer kıyı beyliklerinin de çekindiği zengin ve güçlü bir beylikti.'),
  ('Germiyanoğlu Süleyman Şah\'ın Karamanoğlu baskısına karşı Osmanlılarla akrabalık kurarak kızı Devlet Hatun\'u Şehzade Yıldırım Bayezid ile evlendirmesi sırasında Kütahya, Simav, Eğrigöz ve Tavşanlı\'yı Osmanlı\'ya bırakması nasıl gerçekleşmiştir?', 'Çeyiz (cihaz) yoluyla barışçıl toprak devri olarak', ['Seksen bin altın karşılığında nakit satış sözleşmesiyle', 'Uzun süren kanlı bir meydan savaşının tazminatı olarak', 'İlhanlı hükümdarının gönderdiği zorunlu sınır fermanıyla'], '1381\'deki ünlü düğünle Germiyanoğlu Süleyman Şah beyliğinin en önemli şehirlerini kızının çeyizi olarak Osmanlılara vermiş, kendisi Kula\'ya çekilmiştir.'),
  ('Birgi, Tire, Ayasuluk (Selçuk) ve İzmir çevresinde Aydınoğlu Mehmed Bey tarafından kurulan, güçlü donanmasıyla Ege Denizi\'nde Latinlere kök söktüren Batı Anadolu beyliği hangisidir?', 'Aydınoğulları', ['Isparta ve Eğirdir göller yöresinde kurulan Hamitoğulları', 'Elbistan ve Maraş yaylalarında hüküm süren Dulkadiroğulları', 'Afyonkarahisar kalesi merkezli yaşayan Sahibataoğulları'], '1308 yılında Birgi merkezli kurulan Aydınoğulları Beyliği, Kıbrıs ve Rodos Haçlıları ile Venediklilere karşı Batı Anadolu kıyılarının en büyük denizci gaza gücü olmuştur.'),
  ('İzmir limanını üs edinerek Sakız, Eğriboz, Mora, Girit ve Trakya kıyılarına başarılı deniz akınları düzenleyen, Bizans taht mücadelesinde Kantakuzenos\'a yardım eden ve 1348\'de Haçlılara karşı İzmir Kalesi önünde şehit düşen ünlü denizci bey kimdir?', 'Aydınoğlu Gazi Umur Bey', ['Sinop baskınıyla Ceneviz kadırgalarını batıran Gazi Çelebi', 'İzmir\'de ilk Türk donanmasını inşa ettiren Çaka Bey', 'Kırım\'daki Suğdak limanını fetheden Emir Hüsameddin Çoban'], '\'Düstûrnâme-i Enverî\'de kahramanlıkları destanlaştırılan Gazi Umur Bey, Osmanlıların Rumeli\'ye geçişinden önce Trakya ve Balkan yollarını denizden tanıtan büyük Türk amiralidir.'),
  ('Balıkesir ve Çanakkale çevresinde kurulan \'Karesioğulları Beyliği\'nin 1345 yılında Orhan Gazi döneminde Osmanlı topraklarına katılmasının Türk tarihindeki en önemli stratejik sonucu nedir?', 'İlk katılan beylik olarak donanma ve tecrübeli komutanlarıyla Osmanlı\'nın Rumeli\'ye geçişini sağlaması', ['Anadolu Türk siyasi birliğinin bütün beylikleri kapsayacak biçimde kesin tamamlanması', 'Akdeniz\'deki Kıbrıs ve Rodos adalarının Osmanlı donanmasınca hemen fethedilmesi', 'Osmanlı başkentinin Bursa\'dan alınarak Balıkesir iç kalesine nakledilmesi'], 'Anadolu Türk siyasi birliği yolunda Osmanlı\'ya katılan ilk beylik Karesioğullarıdır; Karesi donanması ile Hacı İlbey, Ece Halil, Gazi Fazıl ve Evrenos Bey Rumeli fetihlerinin öncü kadrosu olmuştur.'),
  ('Manisa ve çevresini Bizans\'tan fethederek bağımsızlığını ilan eden ve Aydınoğulları ile ittifak kurarak Ege Denizi\'nde donanma faaliyetleri yürüten beylik hangisidir?', 'Saruhanoğulları', ['Sinop ve Kastamonu sahillerine hâkim olan Candaroğulları', 'Niksar ve Çarşamba vadisinde kurulan Taceddinoğulları', 'Denizli ve Ladik dokuma havzasını yöneten İnançoğulları'], 'Saruhan Bey tarafından 1313\'te Manisa (Magnesia) merkezli kurulan Saruhanoğulları, Gediz Ovası\'nın tarımsal zenginliğini Ege deniz gaza ve ticaretiyle birleştirmiştir.'),
  ('Muğla, Milas, Beçin ve Balat (Milet) yöresinde kurularak Rodos Şövalyeleriyle mücadele eden ve Venediklilerle Girit üzerinden yoğun dış ticaret yürüten Güneybatı Anadolu beyliği hangisidir?', 'Menteşeoğulları', ['Beyşehir Gölü kıyısında hüküm süren Eşrefoğulları', 'Balıkesir ve Bergama hattında kurulan Karesioğulları', 'Kayseri ve Sivas yaylasına egemen olan Eretna Beyliği'], 'Antik Karya bölgesinde (Muğla-Milas-Beçin-Fethiye) kurulan Menteşeoğulları Beyliği, güçlü donanması ve Venedik ticaret antlaşmalarıyla Güneybatı Ege\'ye Türk mührünü vurmuştur.'),
  ('Kastamonu ve Sinop havzasında Şemseddin Yaman Candar tarafından kurulan, zengin Küre bakır madenlerini işleten ve Sinop tersanesinde dev gemiler inşa eden Karadeniz beyliği hangisidir?', 'Candaroğulları', ['Erzincan ve Kemah vadisinde hüküm süren Mengücekliler', 'Manisa ve Gediz ovasında egemenlik kuran Saruhanoğulları', 'Adana ve Tarsus kıyılarını elinde tutan Ramazanoğulları'], 'Daha sonra İsfendiyar Bey\'den dolayı \'İsfendiyaroğulları\' adıyla da anılan Candaroğulları (1291-1461), Kastamonu bakırı ve Sinop limanıyla Ceneviz-Osmanlı siyasetinde kilit rol oynamıştır.'),
  ('Isparta, Burdur ve Eğirdir Göller Yöresi\'nde Feleküddin Dündar Bey tarafından kurulan \'Hamitoğulları Beyliği\'nin Hüseyin Bey döneminde Akşehir, Beyşehir, Seydişehir, Yalvaç ve Karaağaç\'ı Osmanlı Padişahı I. Murad\'a devretmesi hangi yöntemle olmuştur?', 'Seksen bin altın karşılığında para ile satış yoluyla', ['Şehzade düğününde gelin çeyizi olarak bağışlanmasıyla', 'Mirasçı kalmaması üzerine vasiyetnameyle terk edilmesiyle', 'Deniz savaşında kaybedilen donanmanın fidyesi olarak verilmesiyle'], 'Karamanoğullarının sürekli saldırılarından bunalan Hamitoğlu Kemaleddin Hüseyin Bey, 1381 (I. Kosova öncesi kesin teslim) sürecinde beş önemli şehrini 80 bin altın karşılığında I. Murad\'a satmıştır.'),
  ('Elbistan ve Maraş merkezli olarak Bozok Türkmenlerinden Zeyneddin Karaca Bey tarafından 1337\'de kurulan ve yaklaşık iki asır boyunca Osmanlı Devleti ile Memlük Sultanlığı arasında tampon devlet konumunda bulunan beylik hangisidir?', 'Dulkadiroğulları', ['Sinop limanında Cenevizlilerle savaşan Pervaneoğulları', 'Isparta ve Eğirdir göller bölgesindeki Hamitoğulları', 'Balıkesir ve Çanakkale kıyı şeridindeki Karesioğulları'], 'Maraş-Elbistan-Kırşehir-Bozok hattında kurulan Dulkadiroğulları, hem Osmanlı sarayına gelinler veren (ör. Yavuz Sultan Selim\'in annesi Gülbahar/Ayşe Hatun) hem de Memlüklerle denge siyaseti izleyen güçlü bir Türkmen beyliğidir.'),
  ('Yavuz Sultan Selim döneminde 1515 yılında kazanılan \'Turnadağ Savaşı\' ile Dulkadiroğulları Beyliği\'ne son verilmesinin Osmanlı siyasi tarihi açısından taşıdığı en kritik anlam nedir?', 'Anadolu Türk siyasi birliğinin kesin biçimde tamamlanması', ['Anadolu\'da Osmanlı\'ya katılan ilk Türk beyliğinin alınması', 'Karadeniz\'in tümüyle bir Türk gölü haline getirilmesi', 'Avrupa\'daki Haçlı ordularının Balkanlar\'dan çıkarılması'], 'Çaldıran Seferi dönüşünde 1515 Turnadağ Muharebesi ile Alaüddevle Bozkurt Bey yenilip Dulkadir toprakları Osmanlı\'ya bağlanınca Anadolu Türk siyasi birliği kesin olarak sağlanmıştır.'),
  ('Kösedağ Savaşı sonrasında kurulan ikinci dönem Anadolu Türk beyliklerinin Türkiye Selçuklu Devleti\'nden farklı olarak Türkçe kültür hayatına yaptıkları en kalıcı ve ortak katkı aşağıdakilerden hangisidir?', 'Arapça ve Farsça yerine konuşulan sade Türkçeyi resmi yönetim, bilim ve edebiyat dili yapmaları', ['Anadolu\'daki bütün kervansarayları kapatarak yalnızca deniz ticaretine izin vermeleri', 'Medrese eğitimini kaldırıp sadece askeri kışla okullarında okuma yazma öğretmeleri', 'İkta sistemini terk ederek tüm tarım topraklarını özel çiftliklere dönüştürmeleri'], 'Farsça ve Arapça bilmeyen sade Türkmen beyleri (Karamanoğlu, Germiyanoğlu, Aydınoğlu, Candaroğlu, İnançoğlu) âlim ve şairlerden Kur\'an tefsirlerini, tıp kitaplarını ve mesnevileri Türkçe yazmalarını isteyerek Eski Anadolu Türkçesi Rönesansı\'nı yaratmışlardır.'),
  ('1402 Ankara Savaşı\'nda Yıldırım Bayezid\'i mağlup eden Timur\'un, daha önce Osmanlı topraklarına katılmış olan Anadolu beyliklerinin (Aydın, Saruhan, Menteşe, Germiyan, Karaman, Candar, Hamit) eski hanedan beylerine topraklarını geri vermesinin stratejik amacı nedir?', 'Anadolu\'da tek ve güçlü bir Osmanlı devleti yerine kendisine bağlı parçalı beylikler düzeni kurmak', ['Anadolu Türkmenlerinin tamamını Semerkant\'a götürerek Çin seferinde öncü birlik yapmak', 'Batı Anadolu kıyılarını Bizans İmparatorluğu\'na bağışlayarak İstanbul kuşatmasını ödüllendirmek', 'Beyliklerin gelirleriyle Akdeniz\'de Venedik Cumhuriyeti\'ne karşı büyük bir donanma kurdurmak'], 'Timur arkasında güçlü bir Osmanlı İmparatorluğu bırakmak istemediğinden eski Türkmen beylerini ihya ederek Anadolu Türk siyasi birliğini yaklaşık yarım yüzyıl geriye götürmüştür.'),
  ('Ankara şehrinin 14. yüzyılın ilk yarısında herhangi bir hanedan beyi tarafından değil, esnaf ve fütüvvet reislerinin oluşturduğu özerk bir şehir yönetimiyle idare edilmesi tarihte nasıl adlandırılır?', 'Ankara Ahiler Yönetimi', ['Kسطamonu Çobanoğulları Emirliği', 'Sivas Kadı Burhaneddin Naipliği', 'Kayseri Yabanlu Panayır Meclisi'], 'İlhanlı ve Eretna otoritesinin zayıfladığı dönemde Ankara\'daki Ahi reisleri (Ahi Hüsameddin, Ahi Şerefeddin ailesi) şehrin savunmasını ve idaresini üstlenmiş, 1354-1362 sürecinde kenti Orhan Gazi ve I. Murad\'a devretmiştir.'),
  ('Anadolu\'nun Türkleşme sürecinde Malazgirt sonrası kurulan \'birinci dönem beylikleri\' ile Kösedağ sonrası kurulan \'ikinci dönem beylikleri\'nin coğrafi yayılımları karşılaştırıldığında hangi temel fark görülür?', 'İlk beylikler ağırlıkla Doğu-Orta Anadolu\'da kurulurken ikinci dönem beyliklerinin Batı Anadolu, Ege ve Akdeniz kıyılarını Türkleştirmesi', ['İlk beyliklerin tamamı denizciyken ikinci dönem beyliklerinin denizlerden tamamen uzak kalması', 'İlk beylikler yalnız Türkçe kullanırken ikinci dönem beyliklerinin Farsçayı resmi dil yapması', 'İlk beylikler Moğollara bağlıyken ikinci dönem beyliklerinin Büyük Selçuklu\'ya bağlanması'], 'Saltuklu, Mengücekli, Artuklu ve Danişmendliler Doğu, Güneydoğu ve İç Anadolu\'yu vatan yaparken; Kösedağ sonrası uçlara yığılan Türkmenlerin kurduğu ikinci dönem beylikleri Ege, Marmara ve Akdeniz sahillerinin Türkleşmesini tamamlamıştır.'),
  ('İkinci dönem Anadolu Türk beyliklerinin kurdukları yüzlerce köy, kasaba ve mahallede \'Kayı, Kınık, Avşar, Bayındır, Salur, Çepni, Yüreğir, Dodurga\' gibi adların yoğun biçimde yaşaması tarihçilere neyi kanıtlar?', 'Yirmi dört Oğuz boyunun Anadolu coğrafyasına kalıcı yer adlarıyla (toponimi) damga vurduğunu', ['Köy isimlerinin tamamının İlhanlı vergi memurlarınca Moğolcadan çevrildiğini', 'Oğuz boylarının şehir merkezlerine girmesinin yasaklanıp dağlarda tutulduğunu', 'Her boyun yalnız tek bir beylik sınırları içinde yaşamasına izin verildiğini'], 'Moğol baskısıyla batıya akan Oğuz boyları fethettikleri topraklara kendi boy, oba ve dede-baba adlarını vererek Anadolu\'nun toponimisini (yer adları haritasını) ebediyen Türkleştirmiştir.'),
  ('Germiyanoğulları, Aydınoğulları, Candaroğulları ve Saruhanoğulları medreselerinde yetişen yüzlerce müderris, kadı, tabip ve kâtibin beylikler birleştikçe Bursa, Edirne ve İstanbul\'daki görevlere getirilmesi neyi sağlamıştır?', 'Beyliklerin bilimsel ve bürokratik birikiminin Osmanlı İmparatorluğu\'nun kuruluş harcını oluşturmasını', ['Osmanlı Devleti\'nde eğitim dilinin Türkçe yerine tümüyle Yunancaya çevrilmesini', 'Beylik medreselerinin hepsinin yıkılarak taşlarının İstanbul\'a taşınmasını', 'Taşra şehirlerinde okuryazar nüfusun kalmayıp kültür hayatının sönmesini'], 'Osmanlı Cihan Devleti sıfırdan doğmamış; Türkiye Selçuklularının mirasını geliştiren Germiyan, Aydın, Karaman, Candar ve Eretna ilim-sanat havzalarının yetişmiş insan gücünü kendi potasında birleştirerek yükselmiştir.'),
  ('Sinop yarımadasında Selçuklu fethi sonrasında başlayıp Pervaneoğulları ve Candaroğulları dönemlerinde büyüyen \'Sinop İç Kalesi ve Tersanesi\' Karadeniz jeopolitiğinde hangi doğal üstünlüğe dayanmıştır?', 'Karadeniz\'in kuzey rüzgârlarına kapalı tek doğal liman koyuna hâkim olmasına', ['Kızılırmak üzerinden Konya\'ya kadar gemilerin yüzerek çıkabilmesine', 'Etrafında hiçbir orman bulunmadığı için yangın tehlikesinden uzak olmasına', 'Kış aylarında deniz suyunun donarak Kırım\'a kara köprüsü oluşturmasına'], 'Hırçın Karadeniz kıyısında Boztepe yarımadasının güneyinde rüzgâra korunaklı tek doğal limana sahip olan Sinop, çevresindeki zengin kereste ormanlarıyla birleşerek Selçuklu, Candar ve Osmanlı donanmalarının ana tersanesi olmuştur.'),
  ('Anadolu uygarlıklarından Türkiye Selçuklularına ve Beylikler dönemine uzanan binlerce yıllık süreçte Konya-Aksaray-Kayseri-Sivas ile Efes/Ayasuluk ve Milet/Balat hatlarının her çağda zenginleşmesinin ortak nedeni nedir?', 'Değişmeyen doğal geçitler ve liman ağı üzerinde kıtalararası ticareti buluşturmaları', ['Sadece altın madenlerinin bu şehirlerin surları içinde çıkarılabilmesi', 'Tarih boyunca hiçbir deprem veya askeri kuşatmaya maruz kalmamaları', 'Yalnızca tek bir etnik topluluğun dış dünyaya kapalı yaşam sürdürmesi'], 'Asur Karum yollarından Pers Kral Yolu\'na, İyon limanlarından Selçuklu kervansaraylarına ve Beylik iskelelerine dek Anadolu\'nun jeopolitik geçit ve liman üstünlüğü her uygarlıkta ticari refahın anahtarı olmuştur.'),
];
